function freshState(){return{page:"home",condition:null,finding:null,topic:null,caseIndex:0,casePart:0,caseSelected:null,caseResponses:{},qIndex:0,selected:null,feedback:false,caseAnswer:undefined,caseFocus:null,unitKind:null,unitKey:null,unitSelected:null,unitFeedback:false,readUnlocked:false}}

let state=freshState();
let pageHistory=[];
const PROGRESS_KEY="learntolook-progress-v2";
let progress=loadProgress();

function blankProgress(){return{conditions:[],topics:[],findings:[],cases:[],questions:[],read:[],unitQuestions:[],completed:[]}}
function loadProgress(){
  try{
    const raw=localStorage.getItem(PROGRESS_KEY);
    if(raw){const parsed=JSON.parse(raw);const base=blankProgress();Object.keys(base).forEach(k=>{base[k]=Array.isArray(parsed[k])?parsed[k]:[]});
      // The expanded v6 question/case banks use new identifiers; preserve course-learning progress but reset legacy global question/case completion.
      base.questions=[];
      base.cases=[];
      return base;}
  }catch(e){}
  return blankProgress();
}
function saveProgress(){try{localStorage.setItem(PROGRESS_KEY,JSON.stringify(progress))}catch(e){}}
function markProgress(type,key){if(!progress[type].includes(key)){progress[type].push(key);saveProgress()}}
function unitId(kind,key){return kind+":"+key}
function isUnitRead(kind,key){return progress.read.includes(unitId(kind,key))}
function isUnitQuestionDone(kind,key){return progress.unitQuestions.includes(unitId(kind,key))}
function isUnitComplete(kind,key){return progress.completed.includes(unitId(kind,key))}
function completeUnit(kind,key){const id=unitId(kind,key);if(isUnitRead(kind,key)&&isUnitQuestionDone(kind,key)&&!progress.completed.includes(id)){progress.completed.push(id);saveProgress()}}
function courseUnitTotal(){return conditions.length+topics.length+findings.length}
function courseUnitDone(){const known=[];progress.completed.forEach(id=>{if(!known.includes(id)&&id.indexOf(":")>0)known.push(id)});return known.length}
function progressPercent(){const total=courseUnitTotal();const done=Math.min(total,courseUnitDone());return total?Math.round((done/total)*100):0}
function progressSummary(){return `${courseUnitDone()} of ${courseUnitTotal()} learning topics completed`}
function setNav(name){document.querySelectorAll("nav button").forEach(b=>b.classList.remove("active"));const el=document.getElementById("nav-"+name);if(el)el.classList.add("active")}
function snapshot(){return JSON.parse(JSON.stringify(state,(k,v)=>v===undefined?"__UNDEFINED__":v),(_,v)=>v==="__UNDEFINED__"?undefined:v)}
function pushPage(next,nav,patch={}){pageHistory.push(snapshot());state={...state,...patch,page:next};render();setNav(nav);window.scrollTo(0,0)}
function openRoot(page,nav){pageHistory=[];state=freshState();state.page=page;render();setNav(nav);window.scrollTo(0,0)}
function openResetModal(){
  const modal=document.getElementById("reset-modal");
  if(!modal)return;
  modal.classList.add("show");
  modal.setAttribute("aria-hidden","false");
  document.body.style.overflow="hidden";
  setTimeout(()=>{const btn=modal.querySelector("button.primary");if(btn)btn.focus()},0);
}
function closeResetModal(){
  const modal=document.getElementById("reset-modal");
  if(!modal)return;
  modal.classList.remove("show");
  modal.setAttribute("aria-hidden","true");
  document.body.style.overflow="";
}
function confirmReset(){
  progress=blankProgress();
  try{localStorage.removeItem(PROGRESS_KEY)}catch(e){}
  state=freshState();
  pageHistory=[];
  closeResetModal();
  render();setNav("home");window.scrollTo(0,0);
}
function goHome(){openRoot("home","home")}
function goLearn(){openRoot("learn","learn")}
function goFindings(){openRoot("examination","findings")}
function goCases(){openRoot("cases","cases")}
function goQuestions(){openRoot("questions","questions")}
function back(){
  if(pageHistory.length){
    state=pageHistory.pop();
    render();
    setNav(state.page==="topic"||state.page==="finding"||state.page==="images"?"findings":state.page==="condition"?"learn":state.page==="caseq"?"cases":state.page);
    window.scrollTo(0,0);
    return;
  }
  if(state.page!=="home")goHome();
}
function jsQuote(value){return String(value).replace(/\\/g,"\\\\").replace(/'/g,"\\'").replace(/\n/g,"\\n").replace(/\r/g,"\\r")}
function unitStatus(kind,key){
  const read=isUnitRead(kind,key), questionDone=isUnitQuestionDone(kind,key), complete=isUnitComplete(kind,key);
  if(complete)return `<div class="ok"><b>Topic complete ✓</b><br>You have read all the content and completed the question for this topic.</div>`;
  if(!read)return `<div class="card"><span class="pill">Step 1 of 2</span><h3 style="margin-top:8px">Read all the content</h3><p class="muted">Scroll to the end of this page. The completion button unlocks when you reach the bottom.</p><button id="content-read-btn" class="primary" ${state.readUnlocked?"":"disabled"} onclick="markContentRead('${kind}','${jsQuote(key)}')">${state.readUnlocked?"Mark content as read":"Read to the bottom to unlock"}</button></div>`;
  if(!questionDone)return `<div class="card"><span class="pill">Step 2 of 2</span><h3 style="margin-top:8px">Complete the topic question</h3><p class="muted">Content completed. Answer the question to add this topic to your course progress.</p><button class="primary" onclick="openUnitQuestion('${kind}','${jsQuote(key)}')">Complete topic question →</button></div>`;
  return `<div class="ok"><b>Topic complete ✓</b><br>All content read and question completed.</div>`;
}
function markContentRead(kind,key){
  if(!state.readUnlocked && !isUnitRead(kind,key))return;
  const id=unitId(kind,key);
  if(!progress.read.includes(id)){progress.read.push(id);saveProgress()}
  completeUnit(kind,key);
  render();
}
function readGateScroll(){
  const btn=document.getElementById("content-read-btn");
  if(!btn || isUnitRead(state.unitKind,state.unitKey))return;
  const nearBottom=window.innerHeight+window.scrollY>=document.documentElement.scrollHeight-70;
  if(nearBottom){state.readUnlocked=true;btn.disabled=false;btn.textContent="Mark content as read";}
}
function setupReadGate(){
  window.removeEventListener("scroll",readGateScroll);
  if(!["condition","topic","finding"].includes(state.page))return;
  if(isUnitRead(state.unitKind,state.unitKey))return;
  window.addEventListener("scroll",readGateScroll,{passive:true});
  setTimeout(()=>{
    const btn=document.getElementById("content-read-btn");
    if(!btn)return;
    const shortPage=document.documentElement.scrollHeight<=window.innerHeight+70;
    if(shortPage){state.readUnlocked=true;btn.disabled=false;btn.textContent="Mark content as read";}else{readGateScroll();}
  },0);
}
function openUnitQuestion(kind,key){
  if(!isUnitRead(kind,key)){alert("Please read all the content first.");return;}
  pushPage("unitq","questions",{unitKind:kind,unitKey:key,unitSelected:null,unitFeedback:false,readUnlocked:false});
}
function unitQuestion(){return unitQuestions[state.unitKind]&&unitQuestions[state.unitKind][state.unitKey]?unitQuestions[state.unitKind][state.unitKey]:null}
function pageHead(title){return `<div class="page-head"><button class="back" onclick="back()">←</button><h1>${title}</h1></div>`}
function svg(type){
if(type==="acuity")return `<svg viewBox="0 0 160 130"><rect x="12" y="20" width="136" height="90" rx="8" fill="#fff" stroke="#b8c9d8"/><text x="80" y="55" text-anchor="middle" font-size="22" fill="#10233f">E</text><text x="80" y="77" text-anchor="middle" font-size="16" fill="#10233f">F P</text><text x="80" y="96" text-anchor="middle" font-size="10" fill="#64748b">VISUAL ACUITY</text></svg>`;
if(type==="pupil")return `<svg viewBox="0 0 160 130"><circle cx="52" cy="65" r="35" fill="#f4c7a5" stroke="#8d5b43"/><circle cx="52" cy="65" r="14" fill="#18212b"/><circle cx="108" cy="65" r="35" fill="#f4c7a5" stroke="#8d5b43"/><circle cx="108" cy="65" r="9" fill="#18212b"/><path d="M70 65h20" stroke="#1769aa" stroke-width="3"/><path d="M76 58l14 7-14 7" fill="none" stroke="#1769aa" stroke-width="3"/></svg>`;
if(type==="field")return `<svg viewBox="0 0 160 130"><ellipse cx="80" cy="65" rx="55" ry="40" fill="#eef6fb" stroke="#1769aa" stroke-width="2"/><path d="M80 25v80M30 65h100" stroke="#9fb5c8"/><circle cx="80" cy="65" r="4" fill="#10233f"/><path d="M30 25l45 40-45 40" fill="#f8d9d9" opacity=".9"/></svg>`;
if(type==="fundus")return `<svg viewBox="0 0 160 130"><circle cx="80" cy="65" r="52" fill="#d98955"/><circle cx="58" cy="52" r="12" fill="#eeb58d"/><circle cx="108" cy="73" r="5" fill="#7c3823"/><path d="M58 52C75 58 93 62 108 73M58 52C75 45 92 38 108 34M58 52C46 70 38 82 32 94" stroke="#8f3824" stroke-width="3" fill="none"/></svg>`;
if(type==="movement")return `<svg viewBox="0 0 160 130"><circle cx="80" cy="65" r="48" fill="#fff" stroke="#b8c9d8"/><circle cx="80" cy="65" r="17" fill="#d88d63"/><circle cx="80" cy="65" r="7" fill="#18212b"/><path d="M80 15v30M80 115V85M30 65h30M130 65H100" stroke="#1769aa" stroke-width="4"/><path d="M80 15l-6 10h12zM130 65l-10-6v12z" fill="#1769aa"/></svg>`;
return `<svg viewBox="0 0 160 130"><circle cx="80" cy="65" r="46" fill="#f3a16c"/><circle cx="80" cy="65" r="18" fill="#8e3d26"/><circle cx="80" cy="65" r="8" fill="#1a1512"/><path d="M35 35c22 10 45 8 68-4M33 92c24-9 47-8 94 2" stroke="#b33d2b" stroke-width="4" fill="none"/></svg>`;
}
function render(){
const s=document.getElementById("screen");
if(state.page==="home")s.innerHTML=`<section class="hero"><div class="logo-lockup"><div class="logo-name">LEARN T<span class="eye-mark" aria-hidden="true"></span> LOOK</div><div class="tagline">LEARN • EXAMINE • RECOGNISE • DIAGNOSE</div></div><p class="hero-sub">Practical ophthalmology teaching for medical students and foundation doctors — from first principles to clinical cases.</p><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><b>Course Progress</b><b id="progress-value">${progressPercent()}%</b></div><div class="progress" style="margin-top:9px"><span style="width:${progressPercent()}%"></span></div><div class="muted" style="margin-top:8px;color:#e6f4f6">${progressSummary()}</div><div class="flow"><span>Learn conditions</span><span>Examine the eye</span><span>Recognise findings</span><span>Diagnose cases</span></div></section>
<div class="grid">
<div class="tile" onclick="goLearn()"><div class="icon">📚</div><b>Learn</b><span>Ophthalmic conditions, presentation and management</span></div>
<div class="tile" onclick="goQuestions()"><div class="icon">✓</div><b>Questions</b><span>60 content-based questions to reinforce what you have learned</span></div>
<div class="tile" onclick="goCases()"><div class="icon">🩺</div><b>Clinical Cases</b><span>50 step-by-step cases with assessment, diagnosis, treatment and follow-up</span></div>
<div class="tile" onclick="goFindings()"><div class="icon">◉</div><b>Examination</b><span>Eye examination skills, findings and original diagrams</span></div></div>
<div class="section"><h2>Start with an Emergency</h2></div><div class="card" onclick="openCondition('Retinal detachment')" style="cursor:pointer"><span class="eyebrow">Red Flag</span><h3 style="margin:6px 0 4px">Retinal Detachment</h3><p class="muted">Flashes • new floaters • curtain or field defect</p><button class="secondary">Read the condition →</button></div>
<div class="section"><h2>About This App</h2></div><div class="card"><p><b>Learn To Look</b> is an original educational prototype created for <b>Dr Mohammed Talib</b>. The current interface, teaching diagrams and educational wording were created for this project. No third-party clinical photographs are embedded.</p></div>
<div class="note"><button class="secondary" onclick="openRights()">Content & Rights</button> <button class="secondary" onclick="showHelp()">Help</button><br><br>Educational use only. This is not a clinical decision-support system. Check current local guidance and seek senior/specialist advice for real patients.<br><br>© Dr Mohammed Talib / Learn To Look project.</div>`;
if(state.page==="learn")s.innerHTML=pageHead("Learn")+`<div class="card"><h2>Ophthalmic Conditions</h2><p>Study the presentation, examination findings, assessment, management and red flags for each condition. A topic only counts towards your progress after you have read the full content and completed its question.</p></div><div class="list">${conditions.map((c,i)=>`<div class="row" onclick="openConditionByIndex(${i})"><div><b>${c.name}</b><small>${c.def}</small></div>${isUnitComplete("condition",c.name)?`<span class="complete-badge">✓ Complete</span>`:`<span>›</span>`}</div>`).join("")}</div>`;
if(state.page==="topic"){const d=topicText[state.topic];s.innerHTML=pageHead(state.topic)+`<div class="card"><span class="pill">Examination Skill</span><h2>${d[0]}</h2><p>${d[1]}</p><h3>How to approach it</h3><p>${d[2]}</p><div class="pearl"><b>Clinical pearl</b><br>${d[3]}</div></div><div class="card"><h3>Key examination points</h3><ul><li>Compare both eyes and document laterality.</li><li>Record visual acuity before interpreting other findings.</li><li>Use pupils, fields and movements to help localise disease.</li><li>Examine the anterior/posterior segment as clinically indicated.</li></ul></div><div class="danger"><b>Escalation</b><br>${d[4]}</div>${unitStatus("topic",state.topic)}<div class="buttons" style="margin-top:13px"><button class="secondary" onclick="pushPage('examination','findings')">See examination findings</button></div>`;}
if(state.page==="condition"){const c=state.condition;s.innerHTML=pageHead(c.name)+`<div class="card"><span class="pill">Condition</span><h2>${c.name}</h2><p>${c.def}</p><h3>Symptoms & Findings</h3><ul>${c.findings.map(x=>`<li>${x}</li>`).join("")}</ul></div><div class="card"><h3>Examination</h3><p>${c.exam}</p></div><div class="card"><h3>Investigations & Assessment</h3><p>${c.tests}</p></div><div class="card"><h3>Initial Management</h3><p>${c.management}</p></div><div class="danger"><b>Red Flags / Escalation</b><br>${c.red}</div><div class="pearl" style="margin-top:12px"><b>Exam pearl</b><br>${c.pearl}</div>${unitStatus("condition",c.name)}<div class="buttons" style="margin-top:13px"><button class="primary" onclick="caseFor('${c.name.replace(/'/g,"\'")}')">Work through a case</button><button class="secondary" onclick="pushPage('examination','findings')">Review findings</button></div>`;}
if(state.page==="examination")s.innerHTML=pageHead("Eye Examination")+`<div class="card"><span class="pill">Core Clinical Skill</span><h2>Eye Examination</h2><p>A structured examination for medical students and foundation doctors. Work through the sequence first, then use the findings cards to interpret what you see. Each learning item only counts after the full content is read and its question is completed.</p><div class="ok"><b>Suggested Sequence</b><br>Visual Acuity → Pupils → Visual Fields → Eye Movements → Anterior Segment → Fundoscopy</div></div><div class="section"><h2>Examination Skills</h2></div><div class="list">${topics.slice(0,6).map((t,i)=>`<div class="row" onclick="openTopic(${i})"><div><b>${t[0]}</b><small>${t[1]}</small></div>${isUnitComplete("topic",t[0])?`<span class="complete-badge">✓ Complete</span>`:`<span>›</span>`}</div>`).join("")}</div><div class="section"><h2>Clinical Assessment & Red Flags</h2></div><div class="list">${topics.slice(6).map((t,i)=>`<div class="row" onclick="openTopic(${i+6})"><div><b>${t[0]}</b><small>${t[1]}</small></div>${isUnitComplete("topic",t[0])?`<span class="complete-badge">✓ Complete</span>`:`<span>›</span>`}</div>`).join("")}</div><div class="section"><h2>Key Eye Findings</h2></div><div class="list">${findings.map((f,i)=>`<div class="card finding" onclick="openFinding(${i})" style="cursor:pointer"><div class="diagram">${svg(f.svg)}</div><div><span class="pill">Finding</span><h3 style="margin:8px 0 4px">${f.name}</h3><p class="muted" style="margin:0">${f.what}</p>${isUnitComplete("finding",f.name)?`<span class="complete-badge" style="margin-top:10px">✓ Complete</span>`:`<p style="margin:10px 0 0;color:#1769aa;font-weight:700">Open Teaching Card →</p>`}</div></div>`).join("")}</div><div class="section"><h2>Clinical Image Teaching</h2></div><div class="card"><p>Use the original diagrams to practise recognising the basic visual pattern before moving on to real clinical photographs in a future, properly licensed image bank.</p><button class="primary" onclick="openImages()">Open Clinical Images →</button></div>`;
if(state.page==="images")s.innerHTML=pageHead("Clinical Images")+`<div class="card"><h2>Original Teaching Diagrams</h2><p>These diagrams are created for Learn To Look and are intended to teach patterns. Real patient photographs will only be added when their reuse rights and patient permissions are appropriate.</p></div><div class="grid3">${findings.map((f,i)=>`<div class="card" style="cursor:pointer" onclick="openFinding(${i})"><div class="diagram" style="width:100%;height:145px">${svg(f.svg)}</div><h3 style="margin:10px 0 4px">${f.name}</h3><p class="muted">Open teaching card →</p></div>`).join("")}</div>`;
if(state.page==="finding"){const f=state.finding;s.innerHTML=pageHead(f.name)+`<div class="card finding"><div class="diagram">${svg(f.svg)}</div><div><h2>${f.name}</h2><p>${f.what}</p></div></div><div class="card"><h3>How to examine it</h3><p>${f.how}</p></div><div class="card"><h3>What an abnormal finding may mean</h3><p>${f.abnormal}</p></div><div class="pearl"><b>Remember</b><br>Interpret findings in the clinical context; an isolated sign rarely gives the whole diagnosis.</div>${unitStatus("finding",f.name)}`;}
if(state.page==="unitq"){const q=unitQuestion();const title=state.unitKey||"Topic";if(!q){s.innerHTML=pageHead(title)+`<div class="danger"><b>Question unavailable</b><br>This topic does not yet have a completion question.</div>`;}else{s.innerHTML=pageHead("Topic Question")+`<div class="card"><span class="pill">${title}</span><h2>${q.q}</h2>${q.options.map((x,i)=>`<button class="option ${state.unitFeedback?(i===q.answer?"correct":state.unitSelected===i?"wrong":""):state.unitSelected===i?"selected":""}" ${state.unitFeedback?"disabled":""} onclick="selectUnitAnswer(${i})">${String.fromCharCode(65+i)}. ${x}</button>`).join("")}${state.unitFeedback?`<div class="pearl"><b>${state.unitSelected===q.answer?"Correct":"Review this"}</b><br>${q.explanation}</div><div class="ok"><b>Topic question completed ✓</b><br>This topic is now counted in your course progress.</div><button class="primary" onclick="back()">Back to ${title}</button>`:`<button class="primary" onclick="submitUnitAnswer()" ${state.unitSelected===null?"disabled":""}>Submit answer</button>`}</div>`;}}
if(state.page==="cases"){
  const done=new Set(progress.cases);
  s.innerHTML=pageHead("Clinical Cases")+`<div class="card"><div class="case-bank-head"><div><span class="pill">50 Cases</span><h2>Clinical Cases</h2><p>Work through each case in five stages: assessment, diagnosis, immediate management, treatment, and follow-up/prognosis. Cases are separate from the Questions bank and use clinical scenarios.</p></div><div class="case-bank-count"><b>${done.size}</b><span>of 50 completed</span></div></div></div><div class="list">${cases.map((c,i)=>`<div class="row case-row" onclick="openCase(${i})"><div><span class="pill">Case ${i+1} · ${c.tag}</span><b>${c.title}</b><small>${c.stem}</small></div>${done.has(c.id)?`<span class="complete-badge">✓ Complete</span>`:`<span>›</span>`}</div>`).join("")}</div>`;
}
if(state.page==="caseq"){
  const c=cases[state.caseIndex];
  const part=state.casePart;
  const st=c.steps[part];
  const completed=progress.cases.includes(c.id);
  const answered=state.caseResponses&&Object.prototype.hasOwnProperty.call(state.caseResponses,part);
  const selected=answered?state.caseResponses[part]:null;
  const pct=Math.round(((part+(answered?1:0))/c.steps.length)*100);
  s.innerHTML=pageHead(`Case ${state.caseIndex+1}`)+`<div class="card"><div class="case-meta"><span class="pill">${c.tag}</span><span class="muted">${part+1} of ${c.steps.length}</span></div><h2>${c.title}</h2><p>${c.stem}</p></div><div class="card"><span class="eyebrow">${st.label}</span><h2>${st.q}</h2>${st.options.map((x,i)=>`<button class="option ${answered?(i===st.answer?"correct":selected===i?"wrong":""):(state.caseSelected===i?"selected":"")}" ${answered?"disabled":""} onclick="selectCaseAnswer(${i})">${String.fromCharCode(65+i)}. ${x}</button>`).join("")}${answered?`<div class="pearl"><b>${selected===st.answer?"Correct":"Review this"}</b><br>${st.explanation}</div><div class="case-step-actions">${part>0?`<button class="secondary" onclick="prevCasePart()">← Previous part</button>`:""}${part<c.steps.length-1?`<button class="primary" onclick="nextCasePart()">Next part →</button>`:`<button class="primary" onclick="finishCase()">Complete case ✓</button>`}</div>`:`<button class="primary" onclick="submitCasePart()" ${state.caseSelected===null?"disabled":""}>Submit answer</button>`}</div><div class="progress" style="background:#e7edf3;margin-top:8px"><span style="width:${pct}%;background:#1769aa"></span></div>${completed?`<div class="ok" style="margin-top:12px"><b>Case completed ✓</b><br>You have worked through all five parts of this case.</div>`:""}`;
}
if(state.page==="questions"){
  const q=quiz[state.qIndex];
  const completed=new Set(progress.questions); const done=completed.size; const answered=state.feedback; const selected=state.selected;
  s.innerHTML=pageHead("Questions")+`<div class="card"><div class="question-top"><div><span class="pill">${q.category}</span><div class="muted" style="margin-top:8px">Question ${state.qIndex+1} of ${quiz.length}</div></div><div class="question-score"><b>${done}</b><span>of ${quiz.length} completed</span></div></div><h2>${q.q}</h2>${q.options.map((x,i)=>`<button class="option ${answered?(i===q.answer?"correct":selected===i?"wrong":""):(selected===i?"selected":"")}" ${answered?"disabled":""} onclick="selectAnswer(${i})">${String.fromCharCode(65+i)}. ${x}</button>`).join("")}${answered?`<div class="pearl"><b>${selected===q.answer?"Correct":"Review this"}</b><br>${q.explanation}</div><div class="case-step-actions"><button class="secondary" onclick="prevQuestion()" ${quiz.length===1?"disabled":""}>← Previous</button><button class="primary" onclick="nextQuestion()">${state.qIndex===quiz.length-1?"Start again →":"Next question →"}</button></div>`:`<button class="primary" onclick="submitAnswer()" ${selected===null?"disabled":""}>Submit answer</button>`}</div><div class="progress" style="background:#e7edf3;margin-top:8px"><span style="width:${Math.round((done/quiz.length)*100)}%;background:#1769aa"></span></div><p class="note">These are content-based questions rather than clinical vignettes. Use Clinical Cases for longer step-by-step patient scenarios.</p>`;
}
if(state.page==="rights")s.innerHTML=pageHead("Content & rights")+`<div class="card"><h2>Current Prototype</h2><p>The current app is deliberately built without third-party clinical photographs, copied textbook passages or copied question-bank material.</p><h3>Original project assets</h3><ul><li>Interface and navigation: created for this project.</li><li>Teaching diagrams: created for this project.</li><li>Educational wording, question explanations and clinical case scenarios: written for this project.</li><li>Branding: Learn To Look / Dr Mohammed Talib.</li></ul><div class="pearl"><b>Future asset rule</b><br>Any real fundus photograph, OCT, visual field or other third-party image must have documented permission or a licence that permits this intended use before it is added.</div><p class="muted">Copyright law is jurisdiction-specific. This page is a project record, not a legal opinion.</p></div><div class="card"><h3>Clinical accuracy rule</h3><p>Content is written as educational material and should be reviewed against current local/national guidance before clinical deployment.</p></div>`;
  if(["condition","topic","finding"].includes(state.page))setupReadGate();
}
const quiz=[{"id":"q01","category":"Cataract","q":"Which pattern is most typical of uncomplicated cataract?","options":["Progressive, usually painless visual reduction","Sudden painful visual loss","Pain on eye movement","Purulent discharge with severe pain"],"answer":0,"explanation":"Cataract usually causes gradual visual symptoms, often with glare and reduced contrast.","sourceKind":"condition","sourceKey":"Cataract"},{"id":"q02","category":"Cataract","q":"Which symptom commonly points towards cataract?","options":["Glare and difficulty with night driving","Curtain-like field loss","Painful photophobia","New flashes with floaters"],"answer":0,"explanation":"Glare, reduced contrast and difficulty with night driving are common cataract symptoms.","sourceKind":"condition","sourceKey":"Cataract"},{"id":"q03","category":"Cataract","q":"What is the definitive treatment for a visually significant cataract?","options":["Cataract extraction with intraocular lens implantation","Topical antibiotic drops alone","Panretinal photocoagulation","Immediate vitrectomy"],"answer":0,"explanation":"Cataract surgery is the definitive treatment when the cataract is causing sufficient functional impairment.","sourceKind":"condition","sourceKey":"Cataract"},{"id":"q04","category":"Chronic Open-Angle Glaucoma","q":"Which statement best describes chronic open-angle glaucoma?","options":["A chronic optic neuropathy with characteristic structural and visual-field change","A condition defined only by a high IOP","Usually a sudden painful red eye","A diagnosis made from visual acuity alone"],"answer":0,"explanation":"Glaucoma is an optic neuropathy with characteristic structural and functional damage; IOP is an important risk factor but not the diagnosis by itself.","sourceKind":"condition","sourceKey":"Chronic Open-Angle Glaucoma"},{"id":"q05","category":"Chronic Open-Angle Glaucoma","q":"Which test is used to quantify functional visual-field loss in glaucoma?","options":["Standard automated perimetry","Fluorescein staining","Schirmer testing","Visual evoked potential as the routine first test"],"answer":0,"explanation":"Standard automated perimetry is used to assess and monitor glaucomatous visual-field loss.","sourceKind":"condition","sourceKey":"Chronic Open-Angle Glaucoma"},{"id":"q06","category":"Chronic Open-Angle Glaucoma","q":"Which statement about intraocular pressure in glaucoma is correct?","options":["Glaucoma can occur even when an individual IOP measurement is within the reference range","A normal IOP excludes glaucoma","A high IOP alone proves glaucomatous damage","IOP has no relevance to glaucoma"],"answer":0,"explanation":"Glaucoma is defined by optic nerve and visual-field damage; IOP can be raised or within the reference range.","sourceKind":"condition","sourceKey":"Chronic Open-Angle Glaucoma"},{"id":"q07","category":"Acute Angle-Closure Glaucoma","q":"Which presentation is most concerning for acute angle closure?","options":["Severe ocular pain with blurred vision and nausea","Mild bilateral itching","Gradual painless blur over years","Watery discharge with preserved vision"],"answer":0,"explanation":"Severe pain, visual disturbance and systemic symptoms are classic warning features of acute angle closure.","sourceKind":"condition","sourceKey":"Acute angle-closure glaucoma"},{"id":"q08","category":"Acute Angle-Closure Glaucoma","q":"Which examination finding may occur in acute angle closure?","options":["A mid-dilated poorly reactive pupil","A normal pupil with no symptoms","Only a small reactive pupil in both eyes","Isolated eyelid twitching"],"answer":0,"explanation":"A mid-dilated poorly reactive pupil can occur in an acute angle-closure attack.","sourceKind":"condition","sourceKey":"Acute angle-closure glaucoma"},{"id":"q09","category":"Acute Angle-Closure Glaucoma","q":"What is the appropriate overall management principle for suspected acute angle closure?","options":["Urgent ophthalmic assessment and pressure-lowering treatment","Routine review after several days","Treat as simple conjunctivitis first","Observe without measuring vision"],"answer":0,"explanation":"Acute angle closure is a sight-threatening ophthalmic emergency requiring urgent specialist assessment and treatment.","sourceKind":"condition","sourceKey":"Acute angle-closure glaucoma"},{"id":"q10","category":"Retinal Detachment","q":"Which symptom combination is most concerning for retinal detachment?","options":["Flashes, new floaters and a curtain-like field defect","Itching with watery discharge","Gradual glare only","Pain on eye movement"],"answer":0,"explanation":"The combination of photopsias, new floaters and a field defect is a classic retinal-detachment warning pattern.","sourceKind":"condition","sourceKey":"Retinal detachment"},{"id":"q11","category":"Retinal Detachment","q":"Which examination is particularly important when retinal detachment is suspected?","options":["Urgent dilated retinal examination","Only a colour-vision test","Only measurement of IOP","Only a visual acuity check"],"answer":0,"explanation":"A dilated retinal examination is central to diagnosing retinal tears and detachments.","sourceKind":"condition","sourceKey":"Retinal detachment"},{"id":"q12","category":"Retinal Detachment","q":"Which finding can worsen the visual prognosis of a retinal detachment?","options":["Macular involvement","Mild conjunctival injection","Watery discharge","Normal pupil size"],"answer":0,"explanation":"Central vision can be affected when the macula is detached, which is an important determinant of visual outcome.","sourceKind":"condition","sourceKey":"Retinal detachment"},{"id":"q13","category":"Age-Related Macular Degeneration","q":"Which symptom is particularly suggestive of macular disease?","options":["Central distortion","Isolated eyelid itching","Purulent discharge","Pain on eye movement only"],"answer":0,"explanation":"The macula is responsible for detailed central vision, so distortion and central visual change are important symptoms.","sourceKind":"condition","sourceKey":"Age-related macular degeneration"},{"id":"q14","category":"Age-Related Macular Degeneration","q":"Which investigation is particularly useful when neovascular AMD is suspected?","options":["Optical coherence tomography (OCT)","Schirmer testing","Gonioscopy alone","Confrontation fields only"],"answer":0,"explanation":"NICE recommends OCT in people with suspected late wet AMD; OCT helps assess for neovascular activity and fluid.","sourceKind":"condition","sourceKey":"Age-related macular degeneration"},{"id":"q15","category":"Age-Related Macular Degeneration","q":"How should suspected late wet AMD generally be handled?","options":["Urgent referral to a macula service","Routine review in one year","Treatment with topical antibiotic drops","No assessment if peripheral vision is preserved"],"answer":0,"explanation":"Suspected late wet AMD warrants urgent referral to a macula service because timely assessment and treatment can protect central vision.","sourceKind":"condition","sourceKey":"Age-related macular degeneration"},{"id":"q16","category":"Diabetic Retinopathy","q":"Which statement about diabetic retinopathy is correct?","options":["It can be advanced before the patient notices visual symptoms","It always causes pain early","A normal visual acuity excludes retinopathy","It affects only the optic nerve"],"answer":0,"explanation":"Diabetic retinopathy may be asymptomatic, which is why structured retinal assessment is important.","sourceKind":"condition","sourceKey":"Diabetic retinopathy"},{"id":"q17","category":"Diabetic Retinopathy","q":"Which retinal finding is typical of diabetic retinopathy?","options":["Microaneurysms","A cherry-red spot only","A dendritic corneal ulcer","A fixed mid-dilated pupil"],"answer":0,"explanation":"Microaneurysms are a characteristic early retinal manifestation of diabetic microvascular disease.","sourceKind":"condition","sourceKey":"Diabetic retinopathy"},{"id":"q18","category":"Diabetic Retinopathy","q":"Which imaging test is specifically useful when diabetic macular oedema is suspected?","options":["Optical coherence tomography (OCT)","Gonioscopy","Confrontation testing alone","Ishihara testing alone"],"answer":0,"explanation":"NICE recommends OCT when assessing for diabetic macular oedema.","sourceKind":"condition","sourceKey":"Diabetic retinopathy"},{"id":"q19","category":"Anterior Uveitis","q":"Which combination is typical of anterior uveitis?","options":["Pain, photophobia and reduced vision","Itching alone with normal vision","Gradual glare without inflammation","Purulent discharge without pain"],"answer":0,"explanation":"Anterior uveitis commonly presents with a painful, photophobic red eye and can reduce vision.","sourceKind":"condition","sourceKey":"Anterior uveitis"},{"id":"q20","category":"Anterior Uveitis","q":"Which examination is central to diagnosing anterior uveitis?","options":["Slit-lamp examination for anterior chamber cells and flare","Only confrontation fields","Only a Snellen chart","Only an OCT of the macula"],"answer":0,"explanation":"Slit-lamp examination is central; cells and flare in the anterior chamber support the diagnosis.","sourceKind":"condition","sourceKey":"Anterior uveitis"},{"id":"q21","category":"Anterior Uveitis","q":"Which symptom makes simple conjunctivitis less likely in a red eye?","options":["Significant photophobia","Mild itching","Watery discharge","Gritty discomfort with preserved vision"],"answer":0,"explanation":"Marked photophobia, especially with pain or reduced vision, should prompt consideration of uveitis and other sight-threatening causes.","sourceKind":"condition","sourceKey":"Anterior uveitis"},{"id":"q22","category":"Keratitis","q":"Which history is particularly important in suspected keratitis?","options":["Contact-lens use","Whether the patient prefers tea or coffee","Past cataract surgery only","Whether the patient has seasonal hay fever only"],"answer":0,"explanation":"Contact-lens use, especially with a painful red eye and reduced vision, is an important risk factor for microbial keratitis.","sourceKind":"condition","sourceKey":"Keratitis"},{"id":"q23","category":"Keratitis","q":"Which examination can help identify a corneal epithelial defect?","options":["Fluorescein examination","Gonioscopy","Amsler grid only","Automated perimetry only"],"answer":0,"explanation":"Fluorescein highlights corneal epithelial defects and is an important part of corneal assessment.","sourceKind":"condition","sourceKey":"Keratitis"},{"id":"q24","category":"Keratitis","q":"What is the key management principle for suspected infective keratitis?","options":["Urgent ophthalmic assessment and appropriate antimicrobial treatment","Routine annual review","Treat with lubricants alone in every case","Delay assessment until symptoms persist for a week"],"answer":0,"explanation":"Keratitis can threaten sight; suspected infective disease needs urgent specialist assessment and appropriate treatment.","sourceKind":"condition","sourceKey":"Keratitis"},{"id":"q25","category":"Conjunctivitis","q":"Which feature is most typical of uncomplicated conjunctivitis?","options":["Diffuse redness with discharge and relatively preserved vision","Severe pain with reduced vision","Corneal ulceration with marked photophobia","A fixed mid-dilated pupil"],"answer":0,"explanation":"Simple conjunctivitis commonly causes diffuse conjunctival redness and discharge while vision remains relatively preserved.","sourceKind":"condition","sourceKey":"Conjunctivitis"},{"id":"q26","category":"Conjunctivitis","q":"Which symptom should prompt reconsideration of simple conjunctivitis?","options":["Marked pain or reduced vision","Mild bilateral redness","Watery discharge","Mild gritty discomfort"],"answer":0,"explanation":"Pain, photophobia, corneal opacity or reduced vision suggest a different and potentially sight-threatening diagnosis.","sourceKind":"condition","sourceKey":"Conjunctivitis"},{"id":"q27","category":"Conjunctivitis","q":"Which symptom is particularly suggestive of an allergic component?","options":["Itching","Flashes","Curtain-like field loss","Pain on eye movement"],"answer":0,"explanation":"Itching is a characteristic symptom of allergic conjunctival inflammation.","sourceKind":"condition","sourceKey":"Conjunctivitis"},{"id":"q28","category":"Optic Neuritis","q":"Which presentation is typical of optic neuritis?","options":["Subacute visual loss with pain on eye movement","Purulent discharge with itching","Gradual glare from a cataract","Sudden field loss with flashes and floaters"],"answer":0,"explanation":"Optic neuritis often causes subacute visual loss and pain, particularly with eye movement.","sourceKind":"condition","sourceKey":"Optic neuritis"},{"id":"q29","category":"Optic Neuritis","q":"Which additional bedside finding can support optic nerve dysfunction?","options":["Reduced colour vision and an RAPD when unilateral/asymmetric","Purulent discharge","A large corneal ulcer","Raised IOP as the defining feature"],"answer":0,"explanation":"Reduced colour vision and an RAPD can support the diagnosis of an optic neuropathy when the involvement is asymmetric.","sourceKind":"condition","sourceKey":"Optic neuritis"},{"id":"q30","category":"Optic Neuritis","q":"Which set of assessments is most appropriate early in suspected optic neuritis?","options":["Visual acuity, colour vision, pupils and visual fields","Only IOP","Only the red reflex","Only external inspection"],"answer":0,"explanation":"A focused neuro-ophthalmic examination includes acuity, colour vision, pupils and fields, with further investigation guided by the presentation.","sourceKind":"condition","sourceKey":"Optic neuritis"},{"id":"q31","category":"Papilloedema","q":"What does papilloedema specifically mean?","options":["Optic-disc swelling due to raised intracranial pressure","Any swollen optic disc from any cause","An inflamed conjunctiva","A swollen cornea"],"answer":0,"explanation":"Papilloedema is a mechanism-specific term for disc swelling caused by raised intracranial pressure.","sourceKind":"condition","sourceKey":"Papilloedema"},{"id":"q32","category":"Papilloedema","q":"Which associated symptom can support concern about raised intracranial pressure?","options":["Headache with nausea or transient visual obscurations","Isolated itching","Purulent discharge","Night driving difficulty only"],"answer":0,"explanation":"Headache, nausea and transient visual obscurations can occur with raised intracranial pressure and need context-sensitive assessment.","sourceKind":"condition","sourceKey":"Papilloedema"},{"id":"q33","category":"Papilloedema","q":"What is the overall next step when papilloedema is suspected?","options":["Urgent assessment for the cause of raised intracranial pressure","Routine review in six months","Treat as conjunctivitis","Reassure if visual acuity is normal"],"answer":0,"explanation":"Suspected papilloedema can signal a serious intracranial process and requires urgent investigation of the cause.","sourceKind":"condition","sourceKey":"Papilloedema"},{"id":"q34","category":"Visual Acuity","q":"How should visual acuity usually be recorded?","options":["Test each eye separately and document whether correction was used","Test both eyes together only","Record only the better eye","Do not record correction status"],"answer":0,"explanation":"Each eye should be tested separately, with the relevant correction status recorded.","sourceKind":"topic","sourceKey":"Visual Acuity"},{"id":"q35","category":"Visual Acuity","q":"What does reduced visual acuity represent?","options":["A clinical sign with multiple possible causes","A diagnosis of cataract in every patient","A diagnosis of retinal detachment","Proof of optic neuritis"],"answer":0,"explanation":"Reduced acuity can arise from refractive, corneal, lens, retinal or optic nerve disease and should be interpreted in context.","sourceKind":"topic","sourceKey":"Visual Acuity"},{"id":"q36","category":"Pupils & RAPD","q":"What is the best bedside method for detecting an RAPD?","options":["The swinging-light test","A Snellen chart","Confrontation fields alone","Fundoscopy alone"],"answer":0,"explanation":"The swinging-light test compares the relative afferent pupillary response between the two eyes.","sourceKind":"topic","sourceKey":"Pupils & RAPD"},{"id":"q37","category":"Pupils & RAPD","q":"An RAPD most strongly suggests:","options":["Asymmetric afferent visual pathway dysfunction","An isolated extraocular muscle problem","Simple conjunctivitis","A refractive error"],"answer":0,"explanation":"An RAPD points to asymmetric afferent dysfunction, often involving the optic nerve or severe asymmetric retinal disease.","sourceKind":"topic","sourceKey":"Pupils & RAPD"},{"id":"q38","category":"Eye Movements","q":"What should be assessed during a basic ocular-motility examination?","options":["Diplopia, limitation and nystagmus","Only visual acuity","Only IOP","Only colour vision"],"answer":0,"explanation":"Following a target through the positions of gaze lets you assess alignment, range, diplopia and nystagmus.","sourceKind":"topic","sourceKey":"Eye Movements"},{"id":"q39","category":"Eye Movements","q":"New binocular diplopia should prompt you to consider:","options":["An ocular-motor, neurological or restrictive cause","Only cataract","Only conjunctivitis","Only refractive error"],"answer":0,"explanation":"Binocular diplopia indicates ocular misalignment and may reflect cranial nerve, muscle, neuromuscular or restrictive disease.","sourceKind":"topic","sourceKey":"Eye Movements"},{"id":"q40","category":"Visual Fields","q":"What does confrontation field testing mainly provide?","options":["A bedside screen for gross visual-field loss","A definitive replacement for formal perimetry","A measure of IOP","A direct measure of acuity"],"answer":0,"explanation":"Confrontation testing is a screening examination; formal perimetry is more sensitive and reproducible.","sourceKind":"topic","sourceKey":"Visual Fields"},{"id":"q41","category":"Visual Fields","q":"A homonymous visual-field defect suggests a lesion:","options":["Behind the optic chiasm","In the lens only","In the conjunctiva","At the cornea only"],"answer":0,"explanation":"Homonymous defects indicate post-chiasmal pathway involvement, whereas bitemporal defects suggest chiasmal disease.","sourceKind":"topic","sourceKey":"Visual Fields"},{"id":"q42","category":"Fundoscopy","q":"Which sequence is a useful approach to fundoscopy?","options":["Disc, vessels, macula and then the surrounding retina","Only the macula","Only the retinal vessels","Pupil, iris and then stop"],"answer":0,"explanation":"A systematic sequence reduces the risk of missing significant findings.","sourceKind":"topic","sourceKey":"Fundoscopy"},{"id":"q43","category":"Fundoscopy","q":"Which finding should make you consider optic-nerve pathology?","options":["Disc pallor or abnormal cupping/swelling","Watery discharge","Mild lid crusting","Simple conjunctival redness"],"answer":0,"explanation":"Disc pallor, swelling and abnormal cupping are important optic-disc abnormalities.","sourceKind":"topic","sourceKey":"Fundoscopy"},{"id":"q44","category":"Red Eye","q":"What should be checked early in any red-eye assessment?","options":["Visual acuity, pain, photophobia and contact-lens use","Only discharge colour","Only the fellow eye","Only IOP"],"answer":0,"explanation":"These early features help distinguish simple conjunctival inflammation from corneal, uveal, scleral or glaucomatous disease.","sourceKind":"topic","sourceKey":"Red Eye"},{"id":"q45","category":"Red Eye","q":"Which combination should make you especially concerned about sight-threatening red-eye disease?","options":["Pain, photophobia and reduced vision","Mild itching only","Bilateral watery discharge with normal vision","Stable long-standing redness"],"answer":0,"explanation":"Pain, photophobia and reduced vision are important warning features for keratitis, uveitis, scleritis and acute angle closure.","sourceKind":"topic","sourceKey":"Red Eye"},{"id":"q46","category":"Sudden Visual Loss","q":"Which questions are particularly helpful when assessing sudden visual loss?","options":["One or both eyes, painful or painless, field versus diffuse loss, and associated flashes/floaters","Only age","Only whether glasses are worn","Only whether the patient has conjunctivitis"],"answer":0,"explanation":"Laterality, pain, field pattern and associated symptoms help localise the problem and identify emergencies.","sourceKind":"topic","sourceKey":"Sudden Visual Loss"},{"id":"q47","category":"Sudden Visual Loss","q":"Which symptom combination suggests a retinal emergency?","options":["Sudden painless monocular loss with flashes, floaters or a field defect","Mild bilateral itching","Gradual glare while driving at night","Chronic painless redness"],"answer":0,"explanation":"Sudden painless monocular loss with retinal warning symptoms needs urgent assessment for retinal and vascular causes.","sourceKind":"topic","sourceKey":"Sudden Visual Loss"},{"id":"q48","category":"Ophthalmic Emergencies","q":"Which principle best describes initial management of a sight-threatening ophthalmic emergency?","options":["Recognise the pattern, take immediate safe steps and escalate early","Wait for symptoms to settle","Treat every red eye as conjunctivitis","Avoid documenting visual acuity"],"answer":0,"explanation":"Early recognition and escalation are core principles when sight or life may be threatened.","sourceKind":"topic","sourceKey":"Ophthalmic Emergencies"},{"id":"q49","category":"Ophthalmic Emergencies","q":"Which presentation is most clearly an ophthalmic emergency?","options":["Painful red eye with reduced vision and systemic symptoms","Mild bilateral itching","Stable painless cataract symptoms","Long-standing floaters with no change"],"answer":0,"explanation":"Painful visual loss with systemic symptoms can indicate acute angle closure or another sight-threatening process.","sourceKind":"topic","sourceKey":"Ophthalmic Emergencies"},{"id":"q50","category":"Finding: Visual Acuity","q":"What is the key limitation of reduced visual acuity as a finding?","options":["It is non-specific and must be interpreted with the rest of the examination","It always indicates retinal disease","It excludes corneal disease","It proves glaucoma"],"answer":0,"explanation":"Reduced acuity is a sign, not a diagnosis; localisation requires history and other examination findings.","sourceKind":"finding","sourceKey":"Visual acuity"},{"id":"q51","category":"Finding: RAPD","q":"Which finding most directly localises an RAPD to the afferent visual pathway?","options":["An asymmetric pupillary response when light is moved between eyes","A limitation of abduction","A corneal epithelial defect","A high IOP alone"],"answer":0,"explanation":"An RAPD is evidence of asymmetric afferent dysfunction rather than an ocular-motor problem.","sourceKind":"finding","sourceKey":"RAPD"},{"id":"q52","category":"Finding: Visual Fields","q":"Why should a bedside visual-field defect be considered a screening finding?","options":["Formal perimetry is more sensitive and reproducible for many field defects","Confrontation fields measure IOP instead","Confrontation fields diagnose all retinal disease","The patient never needs further testing"],"answer":0,"explanation":"Confrontation can detect gross defects, but formal perimetry is more sensitive and suitable for quantifying reproducible loss.","sourceKind":"finding","sourceKey":"Visual Fields"},{"id":"q53","category":"Finding: Fundoscopy","q":"Which four areas should be deliberately reviewed during fundoscopy?","options":["Optic disc, vessels, macula and retina","Only the optic disc","Only the macula","Only the vessels"],"answer":0,"explanation":"A systematic fundus examination includes the disc, vessels, macula and the surrounding retina.","sourceKind":"finding","sourceKey":"Fundoscopy"},{"id":"q54","category":"Finding: Eye Movements","q":"An abnormal ocular-motility pattern can help identify:","options":["Cranial-nerve, restrictive or neuromuscular disorders","Only cataract","Only conjunctivitis","Only refractive error"],"answer":0,"explanation":"Movement patterns can help localise ocular-motor or neuromuscular pathology.","sourceKind":"finding","sourceKey":"Eye Movements"},{"id":"q55","category":"Finding: Red Eye","q":"Which red-eye finding should trigger urgent consideration of sight-threatening disease?","options":["Corneal opacity or ulcer, pain, photophobia, RAPD or reduced vision","Mild itching alone","Bilateral watery discharge only","Stable redness with normal vision"],"answer":0,"explanation":"These features are red flags for keratitis, uveitis, scleritis, acute glaucoma or other serious pathology.","sourceKind":"finding","sourceKey":"Red eye examination"},{"id":"q56","category":"Integrated","q":"Which combination best fits the app’s intended clinical learning sequence?","options":["Learn the condition, examine systematically, recognise the finding, then reason to a diagnosis","Start with management before taking a history","Skip examination and go straight to treatment","Use one sign to determine every diagnosis"],"answer":0,"explanation":"The teaching structure deliberately progresses from knowledge to examination, pattern recognition and clinical reasoning.","sourceKind":null,"sourceKey":null},{"id":"q57","category":"Integrated","q":"Which examination finding is most useful for recognising an asymmetric afferent visual pathway problem?","options":["RAPD","Discharge","Conjunctival injection alone","A reduced red reflex"],"answer":0,"explanation":"An RAPD is a key bedside sign of asymmetric afferent dysfunction.","sourceKind":null,"sourceKey":null},{"id":"q58","category":"Integrated","q":"Which pair should most strongly prompt urgent retinal assessment?","options":["New flashes and floaters with a field defect","Mild itch and watery discharge","Glare while driving at night","Long-standing painless blur"],"answer":0,"explanation":"New photopsias and floaters with a field defect are classic retinal-detachment warning symptoms.","sourceKind":null,"sourceKey":null},{"id":"q59","category":"Integrated","q":"Which test is particularly helpful for both glaucoma and macular/diabetic disease, but for different purposes?","options":["Optical coherence tomography (OCT)","Gonioscopy only","Schirmer testing","Fluorescein only"],"answer":0,"explanation":"OCT is used in glaucoma for structural optic-nerve assessment and in macular/diabetic disease for retinal structural assessment.","sourceKind":null,"sourceKey":null},{"id":"q60","category":"Integrated","q":"Which red-eye symptom combination is least consistent with simple conjunctivitis?","options":["Pain, marked photophobia and reduced vision","Mild itch with watery discharge","Gritty discomfort with preserved vision","Mild diffuse redness"],"answer":0,"explanation":"Pain, photophobia and reduced vision should prompt consideration of sight-threatening pathology rather than uncomplicated conjunctivitis.","sourceKind":null,"sourceKey":null}];
const cases=[{"id":"c01","title":"Flashes, Floaters and a Curtain","tag":"Retina","stem":"A 68-year-old presents with sudden new flashes in the right eye, a burst of new floaters and a dark curtain developing from the temporal side. Visual acuity is reduced only mildly.","steps":[{"label":"Assessment","q":"What is the most important next assessment?","options":["Urgent dilated retinal examination","Routine refraction only","Schirmer testing","Routine review in one month"],"answer":0,"explanation":"The symptom pattern requires urgent retinal assessment, including a dilated examination."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Rhegmatogenous retinal detachment","Conjunctivitis","Cataract","Anterior uveitis"],"answer":0,"explanation":"Flashes, sudden floaters and a field defect are classic warning symptoms for retinal detachment."},{"label":"Immediate Management","q":"What is the safest immediate management?","options":["Urgent referral to ophthalmology","Topical antibiotic and routine follow-up","Reassurance without examination","Eye patch and discharge"],"answer":0,"explanation":"A suspected retinal detachment is a sight-threatening emergency requiring urgent specialist assessment."},{"label":"Treatment","q":"What may definitive treatment involve?","options":["Laser/cryotherapy and/or retinal surgery depending on the lesion","Topical lubricants only","Panretinal photocoagulation for every case","Antibiotic ointment alone"],"answer":0,"explanation":"Treatment depends on the retinal break and detachment configuration and may include laser, cryotherapy or retinal surgery."},{"label":"Follow-up & Prognosis","q":"Which factor is particularly important for visual prognosis?","options":["Whether the macula is involved at the time of assessment","The amount of conjunctival redness","Presence of mild itching","The patient wearing glasses"],"answer":0,"explanation":"Macular involvement is a major determinant of central visual outcome; prognosis also depends on the severity and timing of treatment."}]},{"id":"c02","title":"New Floaters without a Field Defect","tag":"Retina","stem":"A 61-year-old notices flashes and several new floaters in one eye but no curtain, field defect or sustained visual loss.","steps":[{"label":"Assessment","q":"What is the key assessment?","options":["Dilated retinal examination to look for retinal tears/detachment","Only a visual-acuity check","Only IOP","Only a red-reflex test"],"answer":0,"explanation":"New flashes and floaters should prompt retinal examination to exclude a tear or detachment."},{"label":"Diagnosis","q":"What diagnosis is commonly considered when there is an acute onset of floaters and flashes without a field defect?","options":["Posterior vitreous detachment","Cataract","Conjunctivitis","Optic neuritis"],"answer":0,"explanation":"Posterior vitreous detachment commonly causes flashes and floaters, but retinal tears must be excluded."},{"label":"Immediate Management","q":"What is the key management principle?","options":["Exclude a retinal tear or detachment promptly","Reassure without examining the retina","Start topical steroids","Treat with glaucoma drops"],"answer":0,"explanation":"The important step is to examine the peripheral retina and exclude sight-threatening pathology."},{"label":"Treatment","q":"What treatment is required for uncomplicated posterior vitreous detachment if no retinal tear or detachment is found?","options":["Usually observation and safety-netting","Immediate vitrectomy in every case","Panretinal photocoagulation","Topical antibiotics"],"answer":0,"explanation":"Uncomplicated posterior vitreous detachment is generally observed, with clear advice to return if new warning symptoms develop."},{"label":"Follow-up & Prognosis","q":"What should the patient be told?","options":["Return urgently for a new curtain, field defect or marked increase in floaters/flashes","No further symptoms need reporting","Visual loss is expected to be permanent","Avoid all normal activity indefinitely"],"answer":0,"explanation":"New or worsening symptoms can indicate a retinal tear or detachment and should trigger urgent reassessment."}]},{"id":"c03","title":"Retinal Tear after Posterior Vitreous Detachment","tag":"Retina","stem":"A 70-year-old with sudden flashes and floaters has a horseshoe retinal tear identified on dilated examination. The retina is not yet detached.","steps":[{"label":"Assessment","q":"What is the key clinical priority?","options":["Prompt specialist treatment to barricade the retinal break","Routine observation for one year","Treating the tear as conjunctivitis","Measuring blood pressure only"],"answer":0,"explanation":"A retinal tear can progress to retinal detachment and needs prompt ophthalmic management."},{"label":"Diagnosis","q":"What is the diagnosis?","options":["Symptomatic retinal tear","Cataract","Dry AMD","Optic neuritis"],"answer":0,"explanation":"A symptomatic horseshoe retinal tear is the most likely diagnosis from the examination."},{"label":"Immediate Management","q":"What should happen next?","options":["Urgent retinal specialist assessment","Routine community review","Topical antihistamine","No follow-up"],"answer":0,"explanation":"Prompt ophthalmic assessment allows treatment before a detachment develops."},{"label":"Treatment","q":"Which treatment may be used to secure the tear?","options":["Laser photocoagulation or cryotherapy","Topical antibiotic alone","Intravitreal anti-VEGF for every tear","Cataract extraction"],"answer":0,"explanation":"Retinal tears may be surrounded by laser or cryotherapy to reduce progression to detachment."},{"label":"Follow-up & Prognosis","q":"What is important after treatment?","options":["Safety-net for new flashes, floaters or field defects and assess for additional retinal pathology","No further review is ever needed","Only assess the cornea","Stop all retinal monitoring"],"answer":0,"explanation":"Additional breaks can occur, so symptom awareness and appropriate retinal follow-up are important."}]},{"id":"c04","title":"Progressive Glare and Reduced Contrast","tag":"Cataract","stem":"A 76-year-old reports gradual worsening vision, glare in bright lights and increasing difficulty driving at night. There is no pain or redness.","steps":[{"label":"Assessment","q":"Which examination is most useful to confirm the likely cause?","options":["Visual acuity plus slit-lamp anterior-segment assessment","Only IOP measurement","Only confrontation fields","Only pupils"],"answer":0,"explanation":"Slit-lamp examination can identify and characterise lens opacity, with acuity documenting functional impact."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Cataract","Acute angle closure","Keratitis","Optic neuritis"],"answer":0,"explanation":"The gradual, painless course with glare and reduced contrast is typical of cataract."},{"label":"Immediate Management","q":"What is appropriate if symptoms are affecting daily life?","options":["Ophthalmic assessment for cataract surgery suitability","Emergency treatment for retinal detachment","Topical antibiotics","No discussion until vision is severely reduced"],"answer":0,"explanation":"Referral is appropriate when cataract symptoms cause functional impairment."},{"label":"Treatment","q":"What is the definitive treatment when indicated?","options":["Cataract surgery with intraocular lens implantation","Topical corticosteroid drops","Panretinal laser","Anti-VEGF injections"],"answer":0,"explanation":"Cataract surgery removes the opaque lens and replaces it with an intraocular lens."},{"label":"Follow-up & Prognosis","q":"Which statement is most appropriate?","options":["Prognosis is generally good when the cataract is the main cause, but coexisting ocular disease can limit visual gain","Cataract inevitably causes sudden blindness","Pain is expected after uncomplicated cataract","No assessment of the fellow eye is needed"],"answer":0,"explanation":"Visual benefit depends on cataract severity and other ocular pathology; gradual visual decline is the usual course."}]},{"id":"c05","title":"Asymptomatic Peripheral Field Loss","tag":"Glaucoma","stem":"A 64-year-old is referred after visual-field testing shows a repeatable arcuate defect. The optic nerve appears cupped and IOP is elevated on Goldmann applanation.","steps":[{"label":"Assessment","q":"Which combination best supports formal glaucoma assessment?","options":["Standard automated perimetry, optic-nerve assessment, Goldmann applanation tonometry and angle assessment","Only visual acuity","Only a non-contact IOP","Only colour vision"],"answer":0,"explanation":"Glaucoma assessment combines structural, functional, pressure and angle findings."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Chronic open-angle glaucoma","Conjunctivitis","Cataract","Optic neuritis"],"answer":0,"explanation":"A characteristic field defect with optic-nerve structural change and raised IOP fits glaucoma."},{"label":"Immediate Management","q":"What is the key management goal?","options":["Reduce the risk of further optic-nerve and visual-field loss","Improve conjunctival redness","Remove the lens","Treat corneal infection"],"answer":0,"explanation":"Management aims to reduce the risk of progression and sight loss."},{"label":"Treatment","q":"Which treatment options may form part of specialist management?","options":["Topical medication, selective laser trabeculoplasty and/or surgery depending on risk and response","Topical antibiotic alone","Panretinal laser for every patient","No treatment if acuity is 6/6"],"answer":0,"explanation":"NICE recommends treatment pathways using medicines, SLT and surgery as appropriate to the patient’s risk and response."},{"label":"Follow-up & Prognosis","q":"What should guide follow-up?","options":["Risk of progression and changes in optic nerve/visual fields","Only the current visual acuity","Only the patient’s age","Only the presence of redness"],"answer":0,"explanation":"Glaucoma requires ongoing monitoring of disease control and structural/functional change."}]},{"id":"c06","title":"Ocular Hypertension without Damage","tag":"Glaucoma","stem":"A 59-year-old has IOP above the usual range on repeat Goldmann measurements, but the optic nerves and visual fields are normal. There is no glaucomatous damage.","steps":[{"label":"Assessment","q":"Which additional measurement can help risk-stratify ocular hypertension?","options":["Central corneal thickness","Fluorescein staining","Amsler grid","Schirmer test"],"answer":0,"explanation":"Central corneal thickness is one factor used to assess risk in ocular hypertension."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Ocular hypertension / glaucoma suspect state","Established glaucoma","Keratitis","Cataract"],"answer":0,"explanation":"Raised IOP without characteristic optic-nerve or field damage is consistent with ocular hypertension rather than established glaucoma."},{"label":"Immediate Management","q":"What is the key next step?","options":["Assess lifetime risk and decide on observation or treatment according to risk and specialist guidance","Start antibiotics","Emergency laser peripheral iridotomy","Immediate vitrectomy"],"answer":0,"explanation":"Management of ocular hypertension depends on estimated risk of future visual impairment."},{"label":"Treatment","q":"Which principle is correct?","options":["Not every person with ocular hypertension requires treatment","All patients require surgery","Topical antibiotics prevent glaucoma","Cataract surgery is the routine first-line treatment"],"answer":0,"explanation":"Treatment is based on risk rather than pressure alone."},{"label":"Follow-up & Prognosis","q":"What matters most on follow-up?","options":["Monitoring IOP, optic-nerve structure and visual fields over time","Only asking about discharge","Only repeating visual acuity","No further review if the patient feels well"],"answer":0,"explanation":"Ocular hypertension can convert to glaucoma, so risk-appropriate monitoring is important."}]},{"id":"c07","title":"Painful Red Eye with Nausea","tag":"Glaucoma Emergency","stem":"A 62-year-old develops severe unilateral eye pain, blurred vision, halos around lights, headache and vomiting. The eye is red and the pupil is poorly reactive.","steps":[{"label":"Assessment","q":"Which measurement is particularly important alongside urgent examination?","options":["Intraocular pressure","Schirmer test","Amsler grid","Colour-vision plate testing alone"],"answer":0,"explanation":"IOP measurement supports assessment of an acute angle-closure attack, within urgent ophthalmic review."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Acute angle-closure glaucoma","Conjunctivitis","Cataract","Optic neuritis"],"answer":0,"explanation":"Severe pain, blurred vision, a red eye and systemic symptoms are classic for acute angle closure."},{"label":"Immediate Management","q":"What is the correct urgency?","options":["Immediate ophthalmic assessment and pressure-lowering treatment","Routine clinic review next month","Topical antibiotic alone","Reassurance"],"answer":0,"explanation":"Acute angle closure is a sight-threatening emergency."},{"label":"Treatment","q":"What definitive intervention may be required once the acute pressure is controlled?","options":["Laser peripheral iridotomy where indicated","Cataract surgery for every patient immediately","Panretinal photocoagulation","Corneal cross-linking"],"answer":0,"explanation":"Laser peripheral iridotomy is commonly used for pupillary-block angle closure once clinically appropriate; management is specialist-led."},{"label":"Follow-up & Prognosis","q":"What is important after the acute episode?","options":["Assess the fellow eye and manage the underlying angle-closure risk under ophthalmology","Discharge without advice","Only review visual acuity","Ignore the fellow eye"],"answer":0,"explanation":"The fellow eye may also be at risk, and long-term management is guided by ophthalmic assessment."}]},{"id":"c08","title":"Central Distortion in an Older Adult","tag":"AMD","stem":"A 79-year-old notices new distortion of straight lines and difficulty reading with one eye. The peripheral field appears preserved.","steps":[{"label":"Assessment","q":"Which investigation is particularly useful?","options":["OCT of the macula","Gonioscopy","Schirmer testing","Confrontation fields alone"],"answer":0,"explanation":"OCT is central to the assessment of suspected late wet AMD."},{"label":"Diagnosis","q":"What is the key diagnosis to consider?","options":["Neovascular (wet) AMD","Conjunctivitis","Cataract only","Acute angle closure"],"answer":0,"explanation":"New central distortion in an older adult is a classic presentation of macular disease, and wet AMD must be considered."},{"label":"Immediate Management","q":"What is the appropriate referral urgency when wet AMD is suspected?","options":["Urgent referral to a macula service","Routine review in one year","No referral if acuity is preserved","Treat with topical antibiotics"],"answer":0,"explanation":"NICE recommends urgent referral for suspected late wet AMD."},{"label":"Treatment","q":"What treatment may be offered when active neovascular AMD is confirmed and treatment is appropriate?","options":["Intravitreal anti-VEGF therapy","Topical antibiotic drops","Panretinal photocoagulation","Cataract extraction alone"],"answer":0,"explanation":"Intravitreal anti-VEGF treatment is a standard therapy for active neovascular AMD."},{"label":"Follow-up & Prognosis","q":"What is the main ongoing clinical issue?","options":["Regular monitoring of macular activity and visual function because disease can reactivate","No further monitoring is needed after the first injection","Only monitor IOP","Only monitor the fellow lens"],"answer":0,"explanation":"Wet AMD often requires ongoing monitoring and treatment according to response and disease activity."}]},{"id":"c09","title":"Drusen and Difficulty Reading","tag":"AMD","stem":"A 74-year-old has gradual bilateral difficulty with fine print. Fundus examination shows drusen without rapid visual decline or new distortion.","steps":[{"label":"Assessment","q":"Which examination should be included when evaluating the new visual symptoms?","options":["Fundus examination including the macula","Only IOP measurement","Only pupils","Only external inspection"],"answer":0,"explanation":"Fundus examination is part of the assessment of visual change and can identify AMD features."},{"label":"Diagnosis","q":"What broad category of disease is most likely?","options":["Early or dry age-related macular degeneration","Acute angle closure","Keratitis","Optic neuritis"],"answer":0,"explanation":"Drusen and gradual central symptoms in an older patient suggest AMD, with the subtype determined by the macular findings."},{"label":"Immediate Management","q":"What is appropriate for stable early/dry disease?","options":["Appropriate primary-eye-care follow-up and safety-netting for new central symptoms","Emergency retinal surgery","Topical steroid drops","Immediate anti-VEGF injection without assessment"],"answer":0,"explanation":"Stable early/dry AMD does not automatically require hospital diagnostic testing; new visual symptoms should prompt reassessment."},{"label":"Treatment","q":"Which approach is appropriate?","options":["Address modifiable risk factors such as smoking and support visual needs according to the clinical picture","Treat with topical antibiotics","Use glaucoma drops to slow AMD","Panretinal laser for drusen"],"answer":0,"explanation":"Risk-factor modification and appropriate visual support are important parts of AMD care."},{"label":"Follow-up & Prognosis","q":"Which new symptom should trigger earlier review?","options":["New distortion or rapid central visual change","Stable reading difficulty over years","Mild itching","A normal IOP"],"answer":0,"explanation":"New distortion or rapid central visual change can indicate conversion to active neovascular disease."}]},{"id":"c10","title":"Diabetic Retinopathy without Symptoms","tag":"Diabetic Eye Disease","stem":"A 58-year-old with type 2 diabetes feels that vision is normal. Retinal imaging shows microaneurysms and scattered intraretinal haemorrhages.","steps":[{"label":"Assessment","q":"What additional information is particularly relevant to eye management?","options":["HbA1c and blood pressure, alongside the ocular findings","Only IOP","Only lens opacity","Only visual acuity"],"answer":0,"explanation":"NICE emphasises access to HbA1c and blood pressure information when managing diabetic retinopathy."},{"label":"Diagnosis","q":"What is the likely process?","options":["Non-proliferative diabetic retinopathy","Cataract alone","Optic neuritis","Acute angle closure"],"answer":0,"explanation":"Microaneurysms and retinal haemorrhages are typical features of diabetic retinopathy, and the absence of symptoms does not exclude disease."},{"label":"Immediate Management","q":"What is the appropriate overall approach?","options":["Stage the retinopathy and coordinate ophthalmic and diabetes care","Reassure and discharge permanently","Treat with topical antibiotics","Start glaucoma surgery"],"answer":0,"explanation":"Management is based on stage and includes coordination of diabetes care with the eye pathway."},{"label":"Treatment","q":"Which measure can help reduce progression risk?","options":["Good long-term diabetes and blood-pressure management, with ophthalmic treatment when indicated","Topical lubricants","Avoid all exercise","Treat IOP regardless of pressure"],"answer":0,"explanation":"NICE recommends attention to long-term diabetes and blood-pressure management to support eye health."},{"label":"Follow-up & Prognosis","q":"Why is follow-up important?","options":["Retinopathy can progress without symptoms, so monitoring is needed according to severity","Normal symptoms mean no further screening is ever needed","Only pain predicts progression","The retina does not change once microaneurysms appear"],"answer":0,"explanation":"Diabetic retinopathy may be asymptomatic, and follow-up intervals depend on disease severity and treatment status."}]},{"id":"c11","title":"Vitreous Haemorrhage in Diabetes","tag":"Diabetic Eye Disease","stem":"A 67-year-old with long-standing diabetes develops sudden painless visual loss and reports a dark haze. Fundus view is obscured and proliferative disease is suspected.","steps":[{"label":"Assessment","q":"Which test can help when the fundus view is obscured?","options":["Ocular ultrasound where indicated","Only a colour chart","Only a near-vision test","Only a Schirmer test"],"answer":0,"explanation":"When the fundus view is obscured, ocular ultrasound can help assess the posterior segment."},{"label":"Diagnosis","q":"What is an important diagnosis to consider?","options":["Vitreous haemorrhage from proliferative diabetic retinopathy","Conjunctivitis","Cataract","Anterior uveitis"],"answer":0,"explanation":"Sudden painless loss with a hazy view in a patient with proliferative disease can be due to vitreous haemorrhage."},{"label":"Immediate Management","q":"What is the appropriate next step?","options":["Urgent ophthalmic assessment and retinal evaluation","Routine annual screening only","Topical antibiotic drops","Reassurance"],"answer":0,"explanation":"Sudden visual loss requires urgent assessment for haemorrhage, retinal detachment and other sight-threatening causes."},{"label":"Treatment","q":"Which treatment strategy may be used for proliferative diabetic retinopathy?","options":["Panretinal photocoagulation and/or anti-VEGF in selected circumstances, with surgery for some complications","Topical lubricants","Cataract extraction in every case","Only observation for all patients"],"answer":0,"explanation":"NICE recommends PRP as a principal treatment for proliferative disease, with anti-VEGF and vitrectomy in selected situations."},{"label":"Follow-up & Prognosis","q":"What determines ongoing management?","options":["Whether the proliferative disease regresses and whether complications such as traction or haemorrhage persist","Only visual acuity at one visit","Only IOP","Only blood pressure"],"answer":0,"explanation":"Follow-up depends on treatment response, regression and complications; ongoing hospital-eye-service monitoring may be required."}]},{"id":"c12","title":"Diabetic Macular Oedema","tag":"Diabetic Eye Disease","stem":"A 60-year-old with diabetes reports difficulty reading. OCT shows retinal thickening involving the macula consistent with diabetic macular oedema.","steps":[{"label":"Assessment","q":"Which imaging test is central to assessing the oedema?","options":["OCT","Gonioscopy","Amsler grid alone","Confrontation field only"],"answer":0,"explanation":"OCT is recommended by NICE when assessing for diabetic macular oedema."},{"label":"Diagnosis","q":"What is the diagnosis?","options":["Diabetic macular oedema","Retinal detachment","Acute angle closure","Optic neuritis"],"answer":0,"explanation":"The symptom pattern and OCT findings fit diabetic macular oedema."},{"label":"Immediate Management","q":"What is an important accompanying management measure?","options":["Review diabetes control and other risk factors alongside ophthalmic treatment","Ignore blood pressure","Treat the fellow eye with antibiotics","Avoid follow-up"],"answer":0,"explanation":"Diabetes and blood pressure management form part of overall care, alongside ophthalmic treatment."},{"label":"Treatment","q":"Which treatment class may be used for clinically significant diabetic macular oedema?","options":["Intravitreal anti-VEGF and other specialist-directed treatments","Topical antibiotic alone","Panretinal laser for every case","Cataract surgery as the primary treatment"],"answer":0,"explanation":"NICE recommends treatment of clinically significant oedema, with options including anti-VEGF and selected steroid/laser approaches depending on the phenotype."},{"label":"Follow-up & Prognosis","q":"What is the key principle of follow-up?","options":["Monitor anatomical and functional response and tailor treatment to the individual eye","Discharge after one treatment with no review","Only monitor IOP","Only review the fellow eye"],"answer":0,"explanation":"Follow-up is individualised according to disease activity, treatment response and visual function."}]},{"id":"c13","title":"Painful Photophobic Red Eye","tag":"Uveitis","stem":"A 34-year-old develops unilateral eye pain, photophobia and blurred vision. There is ciliary injection and the pupil is smaller and irregular than the fellow eye.","steps":[{"label":"Assessment","q":"Which examination is central?","options":["Slit-lamp examination for anterior chamber inflammation","Only Snellen visual acuity","Only IOP","Only confrontation fields"],"answer":0,"explanation":"Slit-lamp examination is central to identifying cells and flare and other anterior-segment findings."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Anterior uveitis","Simple conjunctivitis","Cataract","Retinal detachment"],"answer":0,"explanation":"Pain, photophobia, reduced vision and ciliary injection are typical of anterior uveitis."},{"label":"Immediate Management","q":"What is the appropriate general approach?","options":["Urgent ophthalmic assessment rather than treating as simple conjunctivitis","Routine review next month","Topical antihistamine only","No examination if the pupil is reactive"],"answer":0,"explanation":"A painful photophobic red eye with reduced vision needs specialist assessment."},{"label":"Treatment","q":"What treatment is commonly used after appropriate assessment?","options":["Topical corticosteroid with cycloplegic therapy under specialist direction","Topical antibiotic alone for all cases","Panretinal laser","Intravitreal anti-VEGF for every first episode"],"answer":0,"explanation":"Specialist-led treatment commonly includes topical corticosteroids and cycloplegics after the diagnosis is established."},{"label":"Follow-up & Prognosis","q":"Why is follow-up important?","options":["Inflammation can recur and complications such as synechiae or raised IOP may occur","There is never a need to monitor after symptoms improve","Only visual acuity matters","The fellow eye can always be ignored"],"answer":0,"explanation":"Recurrence and inflammatory complications mean follow-up and monitoring are important."}]},{"id":"c14","title":"Recurrent Unilateral Anterior Uveitis","tag":"Uveitis","stem":"A 29-year-old has their third episode of unilateral painful photophobia. Previous episodes improved but symptoms keep recurring.","steps":[{"label":"Assessment","q":"What should the clinician add to the history?","options":["Ask about recurrent/systemic inflammatory symptoms and prior episodes","Only ask about glasses","Only ask about family cataracts","Only ask about IOP"],"answer":0,"explanation":"Recurrent uveitis warrants a careful ocular and systemic history to guide targeted evaluation."},{"label":"Diagnosis","q":"What is the immediate ophthalmic diagnosis?","options":["Recurrent anterior uveitis","Conjunctivitis","Cataract","Retinal detachment"],"answer":0,"explanation":"The repeated pattern of painful photophobic red eye with anterior inflammation is consistent with recurrent anterior uveitis."},{"label":"Immediate Management","q":"What is the priority during an active episode?","options":["Treat and monitor the intraocular inflammation under ophthalmic supervision","Ignore the episode if vision is good","Use topical antibiotic alone","Wait for spontaneous resolution without assessment"],"answer":0,"explanation":"Active uveitis requires appropriate anti-inflammatory treatment and monitoring of complications."},{"label":"Treatment","q":"Which treatment is commonly used during an uncomplicated anterior episode?","options":["Topical corticosteroid and cycloplegic therapy","Panretinal laser","Anti-VEGF injections","Cataract extraction"],"answer":0,"explanation":"Topical steroid and cycloplegic treatment is commonly used for anterior uveitis under specialist direction."},{"label":"Follow-up & Prognosis","q":"What is the reason for longer-term review?","options":["Recurrence and complications may affect visual function over time","The condition always resolves permanently after one episode","Only IOP matters during follow-up","There is no need to review if pain settles"],"answer":0,"explanation":"Recurrent inflammation can cause ocular complications, so follow-up is tailored to the pattern and severity."}]},{"id":"c15","title":"Contact-Lens Wearer with Severe Pain","tag":"Cornea","stem":"A 22-year-old who wears contact lenses sleeps in them and wakes with a very painful red eye, photophobia and reduced vision. Fluorescein shows a corneal epithelial defect with stromal infiltrate.","steps":[{"label":"Assessment","q":"Which clinical factor should immediately raise concern?","options":["Contact-lens use with pain, photophobia and reduced vision","Mild itching only","Watery discharge only","Stable painless redness"],"answer":0,"explanation":"This symptom combination is highly concerning for sight-threatening keratitis."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Microbial keratitis / corneal ulcer","Simple conjunctivitis","Cataract","Optic neuritis"],"answer":0,"explanation":"Pain, photophobia, reduced vision and a corneal infiltrate in a contact-lens wearer strongly suggest microbial keratitis."},{"label":"Immediate Management","q":"What is the appropriate urgency?","options":["Same-day urgent ophthalmic assessment","Routine review in a week","No examination if pain improves briefly","Only lubricants"],"answer":0,"explanation":"A corneal ulcer can progress rapidly and threatens vision, so urgent specialist care is required."},{"label":"Treatment","q":"Which treatment principle is appropriate?","options":["Prompt antimicrobial treatment directed by ophthalmic assessment","Topical steroid alone as initial therapy","Panretinal laser","Cataract surgery"],"answer":0,"explanation":"Management of suspected infective keratitis requires urgent ophthalmic review and appropriate antimicrobial therapy; steroids are not used alone as initial treatment of infection."},{"label":"Follow-up & Prognosis","q":"Which statement is most accurate?","options":["Prognosis depends on organism, depth, location and speed of treatment; close follow-up is required","All corneal ulcers recover without scarring","Follow-up is unnecessary after the first dose","Central ulcers have no effect on vision"],"answer":0,"explanation":"Visual prognosis varies; central/deep infection and delayed treatment can result in scarring or permanent visual loss."}]},{"id":"c16","title":"Corneal Abrasion after Trauma","tag":"Cornea","stem":"A 30-year-old is struck by a fingernail. The eye is painful and watery, and fluorescein shows a linear epithelial defect. There is no obvious penetrating injury.","steps":[{"label":"Assessment","q":"Which additional feature must be checked carefully?","options":["Visual acuity and signs suggesting a deeper/open-globe injury","Only discharge","Only IOP","Only pupil colour"],"answer":0,"explanation":"Trauma requires visual-acuity assessment and careful examination for deeper injury."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Corneal abrasion","Retinal detachment","Cataract","Papilloedema"],"answer":0,"explanation":"A fluorescein-positive epithelial defect after superficial trauma is consistent with corneal abrasion."},{"label":"Immediate Management","q":"What is the key principle?","options":["Exclude a deeper injury before treating the abrasion","Patch every eye regardless of context","Ignore reduced vision","Start steroid drops without examination"],"answer":0,"explanation":"The priority is to ensure there is no penetrating injury or other serious trauma."},{"label":"Treatment","q":"Which treatment may be used for an uncomplicated abrasion according to local practice?","options":["Lubrication and/or topical treatment with appropriate analgesia and safety-netting","Panretinal laser","Anti-VEGF","Cataract surgery"],"answer":0,"explanation":"Simple abrasions are commonly managed conservatively with lubrication/appropriate topical care and analgesia, with local guidance determining specifics."},{"label":"Follow-up & Prognosis","q":"What should trigger reassessment?","options":["Persistent pain, reduced vision or failure to heal","Complete symptom improvement","Normal pupil response","Mild tearing that resolves"],"answer":0,"explanation":"Persistent symptoms or reduced vision suggest a complication or alternative diagnosis and require review."}]},{"id":"c17","title":"Red Eye with Purulent Discharge","tag":"Conjunctiva","stem":"A 21-year-old develops bilateral red eyes with sticky discharge. Vision is near baseline and there is no significant photophobia or ocular pain.","steps":[{"label":"Assessment","q":"Which finding supports a simple conjunctival process?","options":["Preserved vision with diffuse conjunctival redness and discharge","Marked corneal opacity","Severe pain","RAPD"],"answer":0,"explanation":"Preserved vision and absence of significant pain/photophobia favour uncomplicated conjunctivitis."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Conjunctivitis","Keratitis","Anterior uveitis","Acute angle closure"],"answer":0,"explanation":"The symptoms and lack of red flags fit uncomplicated conjunctivitis."},{"label":"Immediate Management","q":"What is the appropriate general approach?","options":["Clinical assessment, hygiene advice and treatment according to likely cause/local guidance","Emergency retinal surgery","Immediate glaucoma treatment","No hygiene advice"],"answer":0,"explanation":"Most uncomplicated conjunctivitis is managed conservatively or with cause-specific treatment according to local guidance."},{"label":"Treatment","q":"Which feature would make topical antibiotic treatment more likely to be considered?","options":["A clinically suspected bacterial presentation with mucopurulent discharge","Mild itching alone","Flashes and floaters","Pain on eye movement"],"answer":0,"explanation":"Mucopurulent discharge can support a bacterial component, but treatment should follow local guidance and clinical assessment."},{"label":"Follow-up & Prognosis","q":"What should prompt reconsideration of the diagnosis?","options":["Pain, photophobia, corneal opacity or reduced vision","Gradual improvement","Mild watering","Resolution of discharge"],"answer":0,"explanation":"These red flags should prompt assessment for keratitis, uveitis or other sight-threatening disease."}]},{"id":"c18","title":"Itchy Bilateral Red Eyes","tag":"Conjunctiva","stem":"A 20-year-old has recurrent bilateral eye redness and intense itching during the pollen season. Vision is normal and there is no pain.","steps":[{"label":"Assessment","q":"Which symptom is most informative?","options":["Itching","Curtain-like field loss","Pain on eye movement","Severe monocular visual loss"],"answer":0,"explanation":"Intense itching strongly suggests an allergic component."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Allergic conjunctivitis","Keratitis","Anterior uveitis","Retinal detachment"],"answer":0,"explanation":"Bilateral itching with preserved vision and seasonal recurrence fits allergic conjunctivitis."},{"label":"Immediate Management","q":"What is the general approach?","options":["Reduce allergen exposure and use appropriate topical/systemic therapy according to local guidance","Emergency retinal assessment","Glaucoma drops","Panretinal laser"],"answer":0,"explanation":"Management focuses on trigger avoidance and symptom control."},{"label":"Treatment","q":"Which treatment category may help?","options":["Topical antihistamine/mast-cell stabiliser therapy","Topical steroid without specialist oversight for every patient","Intravitreal anti-VEGF","Cycloplegic drops for every case"],"answer":0,"explanation":"Topical anti-allergic therapy may be used according to severity and local guidance."},{"label":"Follow-up & Prognosis","q":"Which finding would change the risk assessment?","options":["New pain, photophobia or reduced vision","Persistent itch alone","Bilateral watering","Normal acuity"],"answer":0,"explanation":"Pain, photophobia and visual loss are not typical of simple allergy and warrant reassessment."}]},{"id":"c19","title":"Subacute Visual Loss with Pain on Eye Movement","tag":"Neuro-ophthalmology","stem":"A 27-year-old develops blurred vision in one eye over several days with pain when moving the eye. Colour vision is reduced and there is an RAPD.","steps":[{"label":"Assessment","q":"Which bedside findings are especially useful?","options":["Visual acuity, colour vision, pupils and visual fields","Only IOP","Only discharge examination","Only the red reflex"],"answer":0,"explanation":"These tests characterise optic-nerve dysfunction and the visual deficit."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Optic neuritis","Cataract","Conjunctivitis","Retinal tear"],"answer":0,"explanation":"Subacute visual loss with pain on eye movement, reduced colour vision and an RAPD is typical of optic neuritis."},{"label":"Immediate Management","q":"What is the appropriate next step?","options":["Prompt neuro-ophthalmic/medical assessment and investigation of the cause","Routine annual review","Topical antibiotic drops","Immediate cataract surgery"],"answer":0,"explanation":"New optic-nerve dysfunction needs prompt assessment and appropriate investigation."},{"label":"Treatment","q":"How should treatment be approached?","options":["According to the underlying cause and specialist assessment","Use topical antibiotic alone","Panretinal laser","Treat every case with glaucoma surgery"],"answer":0,"explanation":"Treatment depends on the clinical context and cause; specialist assessment guides therapy."},{"label":"Follow-up & Prognosis","q":"What determines visual outcome?","options":["The underlying cause and severity, with follow-up of visual function","Only IOP","Only the degree of conjunctival redness","Whether the patient wears glasses"],"answer":0,"explanation":"Prognosis varies with aetiology; visual acuity, colour vision and fields help monitor recovery or progression."}]},{"id":"c20","title":"Blurred Disc Margins with Headache","tag":"Neuro-ophthalmology","stem":"A 36-year-old has several weeks of headache and transient episodes of blurred vision. Both optic discs appear swollen on fundus examination.","steps":[{"label":"Assessment","q":"What is the key concern?","options":["Raised intracranial pressure causing papilloedema","Simple conjunctivitis","Cataract","Dry eye"],"answer":0,"explanation":"Bilateral disc swelling with headache and transient visual obscurations raises concern for papilloedema."},{"label":"Diagnosis","q":"What does the term papilloedema mean?","options":["Disc swelling due to raised intracranial pressure","Any optic-disc pallor","Any red eye","A corneal ulcer"],"answer":0,"explanation":"Papilloedema is specifically caused by raised intracranial pressure."},{"label":"Immediate Management","q":"What is the next step?","options":["Urgent investigation of the cause of raised intracranial pressure","Routine review in six months","Topical steroid drops","No action if acuity is normal"],"answer":0,"explanation":"The underlying intracranial cause must be assessed urgently."},{"label":"Treatment","q":"What is the treatment principle?","options":["Treat the underlying cause and manage raised intracranial pressure under specialist care","Use antibiotic eye drops","Perform cataract surgery","Use panretinal photocoagulation"],"answer":0,"explanation":"Treatment is directed at the underlying cause of raised intracranial pressure."},{"label":"Follow-up & Prognosis","q":"Why does follow-up matter?","options":["Persistent raised intracranial pressure can threaten visual function, so vision and the underlying cause need monitoring","Normal acuity at presentation guarantees safety","Only eye redness matters","No neurological review is needed"],"answer":0,"explanation":"Visual function can deteriorate if raised intracranial pressure persists, making ongoing specialist follow-up essential."}]},{"id":"c21","title":"Sudden Painless Monocular Loss","tag":"Retinal Vascular","stem":"A 72-year-old develops sudden, profound, painless loss of vision in one eye over minutes. There is no red eye and no trauma.","steps":[{"label":"Assessment","q":"What is the most important first step?","options":["Urgent ophthalmic assessment with visual acuity, pupils, fields and fundus evaluation","Routine cataract review","Only check blood pressure next week","Topical antibiotic"],"answer":0,"explanation":"Sudden painless monocular visual loss is a retinal/vascular emergency until proven otherwise."},{"label":"Diagnosis","q":"Which diagnosis should be considered urgently?","options":["Central retinal artery occlusion","Conjunctivitis","Cataract","Anterior uveitis"],"answer":0,"explanation":"Sudden profound painless monocular loss is characteristic of a retinal arterial occlusion pattern."},{"label":"Immediate Management","q":"What is the key management principle?","options":["Immediate specialist assessment and systemic vascular evaluation","Wait for spontaneous recovery without assessment","Treat only the surface of the eye","Routine optometry review"],"answer":0,"explanation":"Retinal artery occlusion can indicate significant vascular disease and requires urgent ophthalmic and medical assessment."},{"label":"Treatment","q":"Which statement is safest?","options":["Management depends on the time of presentation and local retinal-stroke/ophthalmic pathway","Topical antibiotics reverse the occlusion","Cataract surgery is definitive treatment","No treatment is ever indicated"],"answer":0,"explanation":"Management is time-sensitive and pathway-dependent; the patient needs urgent specialist assessment rather than routine eye treatment."},{"label":"Follow-up & Prognosis","q":"Why is medical follow-up important?","options":["There may be an underlying vascular source requiring systemic evaluation and risk-factor management","Only the fellow lens needs review","No systemic assessment is relevant","Prognosis depends only on IOP"],"answer":0,"explanation":"Retinal arterial occlusion may be associated with systemic vascular disease, so medical evaluation is important."}]},{"id":"c22","title":"Sudden Visual Loss with Jaw Pain","tag":"Giant Cell Arteritis","stem":"A 78-year-old develops sudden visual loss in one eye with new temporal headache and jaw pain on chewing.","steps":[{"label":"Assessment","q":"Which additional history is particularly important?","options":["Ask about constitutional symptoms and symptoms of giant cell arteritis","Only ask about spectacle use","Only ask about discharge","Only ask about cataract"],"answer":0,"explanation":"The combination of age, new headache, jaw claudication and visual loss strongly raises concern for giant cell arteritis."},{"label":"Diagnosis","q":"What diagnosis must be considered urgently?","options":["Giant cell arteritis with arteritic visual loss","Conjunctivitis","Cataract","Dry eye"],"answer":0,"explanation":"This is a classic high-risk presentation for GCA and arteritic ocular ischaemia."},{"label":"Immediate Management","q":"What is the key principle?","options":["Immediate medical assessment and treatment should not be delayed while arranging definitive diagnostic tests","Routine outpatient review next month","Topical antibiotic drops","Wait for symptoms to resolve"],"answer":0,"explanation":"Suspected GCA with visual symptoms is a medical emergency; urgent treatment is needed to protect vision in the other eye."},{"label":"Treatment","q":"What type of treatment is required?","options":["Urgent systemic corticosteroid treatment under the GCA pathway","Topical ocular lubricant alone","Panretinal laser","Cataract surgery"],"answer":0,"explanation":"Treatment is systemic and urgent; the exact regimen follows the local GCA pathway."},{"label":"Follow-up & Prognosis","q":"What is the key reason for ongoing follow-up?","options":["The fellow eye is at risk and systemic vasculitis requires monitoring","There is no risk after the first dose","Only IOP needs monitoring","Follow-up is unnecessary if pain settles"],"answer":0,"explanation":"The risk to the fellow eye and the systemic disease both require coordinated follow-up."}]},{"id":"c23","title":"Flashing Zig-zag Visual Phenomena","tag":"Neuro-ophthalmology","stem":"A 25-year-old describes a 20-minute episode of shimmering zig-zag lines affecting both visual fields, followed by headache. There is no persistent deficit.","steps":[{"label":"Assessment","q":"Which feature is particularly helpful?","options":["The bilateral, transient and spreading visual phenomenon with complete recovery","A fixed field defect","Persistent unilateral loss","Painful red eye"],"answer":0,"explanation":"Transient bilateral visual phenomena with full recovery and associated headache can fit migraine aura, but the history must exclude other causes."},{"label":"Diagnosis","q":"What is the most likely explanation if the history is typical and examination is normal?","options":["Migraine with visual aura","Retinal detachment","Acute angle closure","Keratitis"],"answer":0,"explanation":"A transient bilateral scintillating visual phenomenon with full recovery can occur with migraine aura."},{"label":"Immediate Management","q":"What should be done if the pattern is atypical or the neurological examination is abnormal?","options":["Urgent medical assessment for an alternative neurological or ocular cause","Routine reassurance only","Topical antibiotics","Cataract referral"],"answer":0,"explanation":"Atypical, persistent or focal neurological symptoms require assessment for other causes."},{"label":"Treatment","q":"What is the general treatment approach when typical migraine aura is diagnosed?","options":["Address migraine triggers and manage headache according to appropriate clinical guidance","Panretinal laser","Intravitreal anti-VEGF","Glaucoma surgery"],"answer":0,"explanation":"Management is usually migraine-focused rather than ocular treatment."},{"label":"Follow-up & Prognosis","q":"Which feature should prompt urgent reassessment in future episodes?","options":["A persistent monocular deficit, new field defect or other new neurological sign","A familiar brief episode that resolves completely","Mild headache only","Normal vision between episodes"],"answer":0,"explanation":"A change in the pattern, persistent deficit or focal neurological signs should prompt reassessment."}]},{"id":"c24","title":"Sudden Painless Visual Loss with Retinal Haemorrhages","tag":"Retinal Vascular","stem":"A 69-year-old has subacute painless visual reduction. Fundus examination shows widespread retinal haemorrhages and venous engorgement in one eye.","steps":[{"label":"Assessment","q":"Which examination is important?","options":["Dilated fundus examination with visual acuity and assessment of the retina","Only slit-lamp examination","Only pupils","Only tear-film testing"],"answer":0,"explanation":"Retinal vascular disease is assessed with visual function and detailed retinal examination."},{"label":"Diagnosis","q":"What diagnosis should be considered?","options":["Central retinal vein occlusion","Cataract","Conjunctivitis","Anterior uveitis"],"answer":0,"explanation":"Widespread retinal haemorrhages and venous engorgement with painless visual loss suggest CRVO."},{"label":"Immediate Management","q":"What should the clinician consider in addition to the ocular assessment?","options":["Systemic vascular risk-factor assessment","Only contact-lens advice","Only antibiotic drops","No systemic review"],"answer":0,"explanation":"Retinal vein occlusion is associated with systemic vascular risk factors that should be assessed."},{"label":"Treatment","q":"Which treatment may be needed for ocular complications?","options":["Intravitreal therapy and/or laser depending on macular oedema or neovascular complications","Topical antibiotics","Cataract extraction in every case","No treatment can ever be used"],"answer":0,"explanation":"Treatment is tailored to macular oedema and neovascular complications under ophthalmology."},{"label":"Follow-up & Prognosis","q":"What should follow-up focus on?","options":["Visual function, macular oedema and development of retinal neovascularisation","Only IOP","Only conjunctival redness","Only the fellow lens"],"answer":0,"explanation":"CRVO can develop macular oedema or neovascular complications, so follow-up is tailored to these risks."}]},{"id":"c25","title":"Post-cataract Pain and Reduced Vision","tag":"Post-operative","stem":"Five days after uncomplicated cataract surgery, a patient develops increasing eye pain, redness and a significant fall in vision.","steps":[{"label":"Assessment","q":"What is the most important next step?","options":["Urgent ophthalmic assessment for a post-operative complication","Routine postoperative check in one month","Topical antihistamine","Reassurance"],"answer":0,"explanation":"Pain and reduced vision after surgery can indicate serious complications and need urgent assessment."},{"label":"Diagnosis","q":"Which diagnosis must be considered?","options":["Acute postoperative endophthalmitis","Cataract","Allergic conjunctivitis","Dry eye"],"answer":0,"explanation":"Pain, redness and reduced vision after intraocular surgery are red flags for endophthalmitis."},{"label":"Immediate Management","q":"What is the appropriate response?","options":["Urgent referral to an ophthalmology service","Wait for spontaneous improvement","Treat only with lubricants","Routine sight test"],"answer":0,"explanation":"Endophthalmitis can threaten sight and requires urgent specialist management."},{"label":"Treatment","q":"What treatment may be required?","options":["Urgent intraocular/intravitreal antimicrobial treatment under ophthalmology, with surgery in selected cases","Topical antihistamine alone","Cataract surgery again","Panretinal photocoagulation"],"answer":0,"explanation":"Management commonly includes urgent antimicrobial therapy delivered according to the specialist pathway, with vitrectomy in selected severe cases."},{"label":"Follow-up & Prognosis","q":"Which statement is most accurate?","options":["Visual prognosis depends on the severity and speed of treatment, so close follow-up is required","All cases recover fully","No monitoring is needed after the first treatment","Prognosis depends only on IOP"],"answer":0,"explanation":"Endophthalmitis can cause permanent visual loss; outcome is influenced by the severity of infection and prompt treatment."}]},{"id":"c26","title":"Chemical Splash to the Eye","tag":"Ocular Emergency","stem":"A laboratory worker splashes an alkaline cleaning solution into one eye. The eye is painful and vision is blurred.","steps":[{"label":"Assessment","q":"What is the first action?","options":["Immediate copious irrigation while arranging urgent clinical assessment","Wait for a slit-lamp before irrigating","Patch the eye and observe","Apply steroid immediately"],"answer":0,"explanation":"Chemical eye injuries are time-critical: irrigation should begin immediately and continue while urgent assessment is arranged."},{"label":"Diagnosis","q":"What is the key diagnosis?","options":["Chemical ocular injury","Conjunctivitis","Cataract","Optic neuritis"],"answer":0,"explanation":"A chemical exposure with pain and visual disturbance is an ocular chemical injury until proven otherwise."},{"label":"Immediate Management","q":"What is the priority during transfer to specialist care?","options":["Continue thorough irrigation and remove contaminated material where appropriate","Stop irrigation as soon as pain improves","Wait for symptoms to settle","Use antibiotic ointment instead of irrigation"],"answer":0,"explanation":"Irrigation is the critical immediate intervention for chemical eye injury."},{"label":"Treatment","q":"What determines subsequent treatment?","options":["Ocular surface severity assessed by ophthalmology, with supportive and specialist-directed therapy","Only the patient’s age","Only the IOP","Only the amount of tearing"],"answer":0,"explanation":"Later treatment depends on the extent of corneal and conjunctival injury and is specialist-guided."},{"label":"Follow-up & Prognosis","q":"What is important after a chemical injury?","options":["Ongoing ophthalmic follow-up because corneal scarring and other complications can affect vision","No further review once pain settles","Only review the other eye","Follow-up only if the pupil is abnormal"],"answer":0,"explanation":"Chemical injuries can have delayed sequelae, so follow-up is important even after initial improvement."}]},{"id":"c27","title":"Blunt Trauma with Blood in the Anterior Chamber","tag":"Trauma","stem":"A 19-year-old is struck in the eye by a ball and has pain and blurred vision. There is visible blood layering in the anterior chamber.","steps":[{"label":"Assessment","q":"What is the key initial examination priority?","options":["Visual acuity and careful ocular examination for associated injury","Only IOP","Only visual fields","Only fundoscopy"],"answer":0,"explanation":"Traumatic anterior-segment injury requires a structured examination, starting with visual acuity and checking for other injuries."},{"label":"Diagnosis","q":"What is the likely diagnosis?","options":["Traumatic hyphema","Cataract","Conjunctivitis","Optic neuritis"],"answer":0,"explanation":"Blood in the anterior chamber after blunt trauma is a hyphema."},{"label":"Immediate Management","q":"What management principle is important?","options":["Urgent ophthalmic assessment because complications such as raised IOP can occur","Routine review in six months","Topical antihistamine","No follow-up if pain is mild"],"answer":0,"explanation":"Hyphema can lead to raised IOP and other complications, so ophthalmic review is required."},{"label":"Treatment","q":"Which approach may be part of treatment?","options":["Ophthalmic monitoring and pressure/inflammation management according to severity","Panretinal laser in every case","Anti-VEGF injection","Cataract surgery immediately in every case"],"answer":0,"explanation":"Management is guided by the severity of the hyphema and complications, with specialist treatment when needed."},{"label":"Follow-up & Prognosis","q":"What should be monitored?","options":["Visual acuity, IOP and resolution of the hyphema","Only redness","Only the fellow lens","No parameters"],"answer":0,"explanation":"Complications can emerge after the initial injury, making follow-up important."}]},{"id":"c28","title":"Possible Open Globe Injury","tag":"Trauma","stem":"A 42-year-old sustains an eye injury from a high-speed metal fragment. The eye is painful and vision is markedly reduced. There is an irregular pupil.","steps":[{"label":"Assessment","q":"What is the immediate concern?","options":["Open globe injury","Simple conjunctivitis","Cataract","Dry eye"],"answer":0,"explanation":"High-velocity trauma with marked visual loss and an abnormal pupil is concerning for an open globe."},{"label":"Diagnosis","q":"What is the safest diagnostic approach?","options":["Urgent specialist assessment with imaging when indicated, avoiding pressure on the eye","Tonometry to measure IOP before anything else","Routine slit-lamp examination with forceful manipulation","Only visual fields"],"answer":0,"explanation":"When open globe is suspected, avoid pressure on the eye; urgent specialist assessment and appropriate imaging may be required."},{"label":"Immediate Management","q":"What should be done while awaiting specialist care?","options":["Protect the eye with a rigid shield and avoid pressure or manipulation","Apply an eye pad tightly","Measure IOP repeatedly","Remove protruding material in the ED"],"answer":0,"explanation":"The eye should be protected without applying pressure, and manipulation should be avoided."},{"label":"Treatment","q":"What treatment is required?","options":["Urgent surgical repair by ophthalmology","Topical lubricants only","Panretinal photocoagulation","Routine cataract review"],"answer":0,"explanation":"Open globe injuries generally require urgent operative repair by an ophthalmic team."},{"label":"Follow-up & Prognosis","q":"What affects prognosis?","options":["Extent of ocular damage and associated retinal/optic-nerve injury","Only the amount of redness","Only the patient’s age","Only the IOP"],"answer":0,"explanation":"Outcome depends on the severity and location of the injury and associated intraocular damage."}]},{"id":"c29","title":"Proptosis and Pain on Eye Movement","tag":"Orbit","stem":"A 45-year-old develops fever, painful eye movements, eyelid swelling and progressive unilateral proptosis.","steps":[{"label":"Assessment","q":"Which additional assessment is particularly important?","options":["Visual acuity, pupils, ocular motility and systemic observations","Only the conjunctiva","Only IOP","Only refraction"],"answer":0,"explanation":"Orbital disease can threaten vision and requires assessment of visual function and ocular motility."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Orbital cellulitis","Simple conjunctivitis","Cataract","Dry eye"],"answer":0,"explanation":"Fever, painful ophthalmoplegia and proptosis strongly suggest orbital rather than preseptal infection."},{"label":"Immediate Management","q":"What is the appropriate urgency?","options":["Urgent hospital and specialist assessment with imaging as indicated","Routine outpatient review","Topical antibiotic alone","No imaging or review if acuity is normal"],"answer":0,"explanation":"Orbital cellulitis can cause sight- and life-threatening complications and needs urgent hospital management."},{"label":"Treatment","q":"What treatment is usually required?","options":["Systemic antimicrobial therapy with surgical drainage in selected cases","Topical antihistamine alone","Cataract surgery","Panretinal laser"],"answer":0,"explanation":"Management usually involves systemic antibiotics and surgery where abscess or other complications require it."},{"label":"Follow-up & Prognosis","q":"What complication must be watched for?","options":["Visual loss, optic-nerve compromise or intracranial spread","Only dry eye","Only cataract","No complications once pain improves"],"answer":0,"explanation":"Orbital cellulitis can threaten vision and spread intracranially, so close monitoring is important."}]},{"id":"c30","title":"Mild Lid Swelling without Orbital Signs","tag":"Orbit","stem":"A 9-year-old has fever and unilateral eyelid swelling after an upper respiratory infection. Eye movements are full, vision is normal and there is no proptosis.","steps":[{"label":"Assessment","q":"Which findings help distinguish preseptal from orbital disease?","options":["Normal ocular motility, normal vision and absence of proptosis favour preseptal disease","Severe pain with movement and proptosis","Marked RAPD","Complete ophthalmoplegia"],"answer":0,"explanation":"Normal vision/motility and no proptosis suggest infection anterior to the orbital septum."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Preseptal (periorbital) cellulitis","Orbital cellulitis","Keratitis","Acute angle closure"],"answer":0,"explanation":"The absence of orbital signs supports preseptal cellulitis."},{"label":"Immediate Management","q":"What is the key principle?","options":["Assess severity and arrange appropriate medical treatment with clear safety-netting for orbital signs","Ignore the eye examination","Use topical lubricants only","Perform retinal laser"],"answer":0,"explanation":"Treatment depends on age and severity, with safety-netting for progression to orbital disease."},{"label":"Treatment","q":"Which treatment may be used?","options":["Appropriate systemic antibiotics according to local guidance","Panretinal photocoagulation","Anti-VEGF","Cataract extraction"],"answer":0,"explanation":"Systemic antibiotics are commonly used, with escalation based on clinical severity and local pathway."},{"label":"Follow-up & Prognosis","q":"Which new finding should prompt urgent reassessment?","options":["Painful eye movements, reduced vision or proptosis","Resolution of fever","Improving swelling","Normal eye movements"],"answer":0,"explanation":"New orbital signs raise concern for progression and require urgent reassessment."}]},{"id":"c31","title":"Ptosis, Diplopia and a Dilated Pupil","tag":"Neuro-ophthalmology","stem":"A 63-year-old develops sudden ptosis, headache and diplopia. The affected pupil is larger than the other pupil.","steps":[{"label":"Assessment","q":"Which finding makes this particularly urgent?","options":["A pupil-involving third-nerve palsy pattern","Mild itching","A normal red reflex","Stable cataract"],"answer":0,"explanation":"A painful or acute pupil-involving third-nerve palsy can be due to compressive disease and needs urgent assessment."},{"label":"Diagnosis","q":"What is the likely localisation?","options":["Cranial nerve III palsy","CN VI palsy only","Conjunctivitis","Cataract"],"answer":0,"explanation":"Ptosis, diplopia and a dilated pupil fit an oculomotor nerve palsy pattern."},{"label":"Immediate Management","q":"What should happen?","options":["Urgent neurological/ophthalmic assessment and vascular imaging as indicated","Routine review in six months","Topical antibiotic","Reassurance"],"answer":0,"explanation":"A pupil-involving third-nerve palsy can signal compressive vascular pathology and warrants urgent evaluation."},{"label":"Treatment","q":"Which statement is safest?","options":["Treat the underlying cause once identified; definitive management is cause-dependent","Use lubricants as definitive treatment","Perform cataract extraction","Use anti-VEGF"],"answer":0,"explanation":"Management is directed at the cause of the nerve palsy."},{"label":"Follow-up & Prognosis","q":"What is important during follow-up?","options":["Monitor ocular alignment, pupil findings and recovery while addressing the underlying cause","Only monitor IOP","Only assess the lens","No neurological follow-up"],"answer":0,"explanation":"Recovery varies with aetiology, so both ocular and neurological follow-up are important."}]},{"id":"c32","title":"Vertical Diplopia Worse on Down-Gaze","tag":"Neuro-ophthalmology","stem":"A 40-year-old has vertical diplopia, especially when descending stairs. The head is tilted to compensate.","steps":[{"label":"Assessment","q":"Which examination is most useful?","options":["Assess ocular motility and alignment in different positions of gaze","Only visual acuity","Only IOP","Only fundus examination"],"answer":0,"explanation":"Patterned ocular-motility testing helps localise a cranial nerve or muscle disorder."},{"label":"Diagnosis","q":"Which cranial nerve pattern should be considered?","options":["Cranial nerve IV palsy","Cranial nerve VI palsy","Optic neuritis","Conjunctivitis"],"answer":0,"explanation":"CN IV palsy commonly produces vertical diplopia that is worse in downgaze and with compensatory head posture."},{"label":"Immediate Management","q":"What is the appropriate next step in a new unexplained case?","options":["Assess for neurological or traumatic causes and refer appropriately","Treat with topical antibiotic","Perform cataract surgery","Observe without examining motility"],"answer":0,"explanation":"New diplopia requires localisation and consideration of neurological or traumatic causes."},{"label":"Treatment","q":"What treatment may be used depending on cause and persistence?","options":["Observation, prisms or strabismus surgery depending on the case","Anti-VEGF injections","Panretinal laser","Topical antibiotic only"],"answer":0,"explanation":"Management varies with cause, duration and severity; prisms or surgery may be considered in selected cases."},{"label":"Follow-up & Prognosis","q":"What should guide follow-up?","options":["Change in ocular alignment, symptoms and evidence of underlying neurological disease","Only IOP","Only visual acuity","Only pupil size"],"answer":0,"explanation":"Follow-up depends on the clinical course and underlying cause."}]},{"id":"c33","title":"Horizontal Diplopia with Abduction Weakness","tag":"Neuro-ophthalmology","stem":"A 71-year-old develops horizontal binocular diplopia. On examination one eye cannot abduct fully.","steps":[{"label":"Assessment","q":"What examination finding localises the problem?","options":["Limited abduction of one eye","Reduced red reflex","Corneal opacity","Macular distortion"],"answer":0,"explanation":"Abduction weakness localises the deficit towards the lateral rectus/CN VI pathway."},{"label":"Diagnosis","q":"What is the most likely localisation?","options":["Cranial nerve VI palsy","Cranial nerve IV palsy","Cataract","Conjunctivitis"],"answer":0,"explanation":"An isolated abduction deficit is characteristic of a sixth-nerve palsy pattern."},{"label":"Immediate Management","q":"What should happen in a new adult case?","options":["Assess for neurological and vascular causes and refer appropriately","Treat with lubricants alone","Only check IOP","Routine annual review"],"answer":0,"explanation":"New binocular diplopia warrants appropriate neuro-ophthalmic assessment."},{"label":"Treatment","q":"Which management may be used while the cause is addressed?","options":["Cause-specific management with temporary occlusion/prism in selected patients","Topical antibiotic alone","Panretinal laser","Cataract surgery"],"answer":0,"explanation":"Treatment depends on the cause; prisms or occlusion can help symptoms in selected cases while recovery occurs."},{"label":"Follow-up & Prognosis","q":"What determines follow-up?","options":["Evolution of the palsy and whether the underlying cause has resolved or requires further treatment","Only the IOP","Only visual acuity","Only redness"],"answer":0,"explanation":"The clinical trajectory and cause guide reassessment and prognosis."}]},{"id":"c34","title":"Fluctuating Diplopia and Ptosis","tag":"Neuro-ophthalmology","stem":"A 49-year-old reports fluctuating ptosis and binocular diplopia that worsen later in the day and improve with rest.","steps":[{"label":"Assessment","q":"Which feature is most informative?","options":["Fatigability and variability of ocular-motor symptoms","Photophobia","Corneal opacity","New floaters"],"answer":0,"explanation":"Fatigable, variable ptosis and diplopia suggest a neuromuscular junction disorder."},{"label":"Diagnosis","q":"Which diagnosis should be considered?","options":["Ocular myasthenia gravis","Cataract","Retinal detachment","Keratitis"],"answer":0,"explanation":"Fluctuating ptosis and diplopia are typical of ocular myasthenia."},{"label":"Immediate Management","q":"What is important clinically?","options":["Assess for generalised or bulbar symptoms and arrange specialist neurology/ophthalmology assessment","Treat as conjunctivitis","Use topical steroids alone","Ignore if pupils are normal"],"answer":0,"explanation":"Myasthenia can generalise and requires appropriate neurological assessment."},{"label":"Treatment","q":"Which approach is appropriate?","options":["Cause-specific neuromuscular treatment under specialist care","Panretinal laser","Cataract extraction","Topical antibiotic"],"answer":0,"explanation":"Treatment is systemic/specialist and depends on disease severity and subtype."},{"label":"Follow-up & Prognosis","q":"What should follow-up include?","options":["Monitoring symptom control and any progression beyond the ocular muscles","Only visual acuity","Only IOP","No follow-up if symptoms fluctuate"],"answer":0,"explanation":"Ocular myasthenia may remain ocular or generalise, so clinical follow-up matters."}]},{"id":"c35","title":"Restricted Elevation with Proptosis","tag":"Orbit","stem":"A 53-year-old has bilateral proptosis, dry gritty eyes and restricted elevation. There is no severe pain.","steps":[{"label":"Assessment","q":"Which ocular findings are particularly relevant?","options":["Motility, lid position, corneal exposure and visual function","Only visual acuity","Only IOP","Only the red reflex"],"answer":0,"explanation":"Orbital disease can affect movement, lids, cornea and optic-nerve function."},{"label":"Diagnosis","q":"Which condition should be considered?","options":["Thyroid eye disease","Conjunctivitis","Cataract","Retinal detachment"],"answer":0,"explanation":"Bilateral proptosis and restrictive motility impairment fit thyroid eye disease."},{"label":"Immediate Management","q":"What is an important risk to assess?","options":["Corneal exposure and optic-nerve compromise","Only itching","Only cataract","Only IOP"],"answer":0,"explanation":"Severe thyroid eye disease can threaten the cornea or optic nerve."},{"label":"Treatment","q":"Which treatment strategy may be needed?","options":["Supportive ocular-surface care plus specialist orbital/thyroid management according to severity","Panretinal photocoagulation","Topical antibiotic for every case","Cataract surgery"],"answer":0,"explanation":"Management depends on activity and severity and may range from lubrication to specialist medical/surgical orbital treatment."},{"label":"Follow-up & Prognosis","q":"What should be monitored?","options":["Visual function, corneal exposure, motility and disease activity","Only redness","Only IOP","Nothing once symptoms stabilise"],"answer":0,"explanation":"Thyroid eye disease can change over time and follow-up is guided by activity and risk to vision."}]},{"id":"c36","title":"Pain Out of Proportion with a Red Eye","tag":"Sclera","stem":"A 58-year-old with autoimmune disease has deep severe ocular pain and a violaceous-red eye. Vision is blurred.","steps":[{"label":"Assessment","q":"Which features are most important?","options":["Visual acuity, pain severity and deep ocular examination","Only discharge","Only refraction","Only IOP"],"answer":0,"explanation":"Deep pain and reduced vision in a red eye require careful examination for scleritis and other sight-threatening disease."},{"label":"Diagnosis","q":"What diagnosis should be considered?","options":["Scleritis","Simple conjunctivitis","Cataract","Allergic eye disease"],"answer":0,"explanation":"Severe deep ocular pain with a violaceous hue is characteristic of scleritis."},{"label":"Immediate Management","q":"What is the appropriate urgency?","options":["Urgent ophthalmic assessment","Routine community review","Topical antihistamine alone","No assessment if the eye is not photophobic"],"answer":0,"explanation":"Scleritis can be associated with serious ocular and systemic disease and warrants prompt assessment."},{"label":"Treatment","q":"Which treatment may be required?","options":["Systemic anti-inflammatory therapy directed by ophthalmology, with treatment of any underlying systemic disease","Topical antibiotic alone","Cataract surgery","Panretinal laser"],"answer":0,"explanation":"Scleritis often requires systemic anti-inflammatory treatment and assessment for associated systemic disease."},{"label":"Follow-up & Prognosis","q":"Why is follow-up important?","options":["Recurrence, structural complications and associated systemic disease can affect outcome","Scleritis never recurs","Only IOP matters","No systemic follow-up is relevant"],"answer":0,"explanation":"Scleritis can threaten vision and may reflect systemic inflammatory disease."}]},{"id":"c37","title":"Sectoral Redness with Little Pain","tag":"Sclera","stem":"A 32-year-old has a focal, bright-red area on the white of the eye. There is mild discomfort but no photophobia or visual loss.","steps":[{"label":"Assessment","q":"Which feature supports a superficial process?","options":["Mild discomfort with preserved vision and no photophobia","Severe deep pain","Reduced vision","Corneal opacity"],"answer":0,"explanation":"Mild symptoms with preserved vision and no photophobia are more consistent with a superficial inflammation."},{"label":"Diagnosis","q":"What is a likely diagnosis?","options":["Episcleritis","Keratitis","Anterior uveitis","Acute angle closure"],"answer":0,"explanation":"A focal superficial red eye with mild symptoms can be episcleritis."},{"label":"Immediate Management","q":"What is appropriate?","options":["Confirm that there are no red flags and manage symptomatically according to local guidance","Emergency retinal surgery","Immediate anti-VEGF","Glaucoma surgery"],"answer":0,"explanation":"Episcleritis is usually self-limited but the diagnosis should be distinguished from scleritis and keratitis."},{"label":"Treatment","q":"Which option may be considered?","options":["Lubrication and/or topical anti-inflammatory therapy according to the clinical picture","Intravitreal therapy","Panretinal laser","Cataract extraction"],"answer":0,"explanation":"Treatment is generally supportive or topical anti-inflammatory depending on symptoms and local practice."},{"label":"Follow-up & Prognosis","q":"What is typical?","options":["Generally good prognosis, with reassessment if pain or visual symptoms develop","Rapid permanent blindness in most cases","No need to reconsider the diagnosis","Routine retinal surgery"],"answer":0,"explanation":"Episcleritis generally has a good prognosis, but atypical features should trigger reassessment."}]},{"id":"c38","title":"Central Distortion and Reading Difficulty","tag":"Macula","stem":"A 72-year-old reports distortion of straight lines and difficulty reading. Visual acuity is reduced and the macular reflex looks abnormal.","steps":[{"label":"Assessment","q":"What is the key ocular examination?","options":["Fundus examination of the macula with OCT when indicated","Only IOP","Only pupils","Only external inspection"],"answer":0,"explanation":"Macular symptoms should prompt focused fundus assessment and OCT when clinically indicated."},{"label":"Diagnosis","q":"Which condition is most likely?","options":["Macular disease such as AMD","Conjunctivitis","Acute angle closure","Keratitis"],"answer":0,"explanation":"Central distortion and reading difficulty suggest macular pathology."},{"label":"Immediate Management","q":"What symptom would increase urgency?","options":["New rapid distortion or sudden central visual change","Long-standing stable blur","Mild itch","Normal IOP"],"answer":0,"explanation":"Rapid or new central change can indicate active neovascular disease and needs prompt assessment."},{"label":"Treatment","q":"What treatment depends on the diagnosis?","options":["AMD treatment may include intravitreal anti-VEGF for active neovascular disease","Topical antibiotics for all macular disease","Panretinal laser for all cases","No treatment is possible"],"answer":0,"explanation":"Treatment is diagnosis-specific; active neovascular AMD may require anti-VEGF therapy."},{"label":"Follow-up & Prognosis","q":"Which factor matters to prognosis?","options":["Severity and chronicity of the macular disease and response to treatment","Only the IOP","Only the fellow-eye pupil","Only conjunctival appearance"],"answer":0,"explanation":"Visual outcome depends on the underlying macular pathology, structural damage and treatment response."}]},{"id":"c39","title":"Abnormal Fundus in Hypertension and Diabetes","tag":"Retina","stem":"A 57-year-old with diabetes and hypertension has reduced vision. Fundus examination shows retinal haemorrhages and exudates.","steps":[{"label":"Assessment","q":"What examination is most important?","options":["Systematic dilated fundus examination and retinal imaging as indicated","Only a visual-acuity check","Only IOP","Only pupils"],"answer":0,"explanation":"Retinal vascular disease is assessed by systematic fundus examination and appropriate imaging."},{"label":"Diagnosis","q":"What broad category should be considered?","options":["Diabetic and/or hypertensive retinal vascular disease","Cataract only","Optic neuritis","Conjunctivitis"],"answer":0,"explanation":"Retinal haemorrhages and exudates in a patient with diabetes/hypertension raise concern for retinal microvascular disease."},{"label":"Immediate Management","q":"What should accompany the eye assessment?","options":["Review systemic risk factors and coordinate medical and ophthalmic care","Only give lubricants","Ignore blood pressure","Treat with cataract surgery"],"answer":0,"explanation":"Systemic control of diabetes and blood pressure is part of reducing ocular risk."},{"label":"Treatment","q":"Which principle is correct?","options":["Ophthalmic treatment depends on disease stage and macular/proliferative complications","Every retinal haemorrhage needs panretinal laser","Every case requires anti-VEGF","No treatment is ever needed"],"answer":0,"explanation":"Treatment is stage- and phenotype-dependent and may include laser, anti-VEGF or surgery."},{"label":"Follow-up & Prognosis","q":"What determines monitoring intensity?","options":["Disease severity, activity, treatment status and systemic risk factors","Only age","Only visual acuity on the day","Only pupil size"],"answer":0,"explanation":"Monitoring frequency is individualised to the retinal disease and systemic risk profile."}]},{"id":"c40","title":"Lost Peripheral Vision","tag":"Glaucoma / Visual Fields","stem":"A 66-year-old notices difficulty noticing objects to either side but has no pain. Formal field testing shows a pattern of progressive peripheral loss.","steps":[{"label":"Assessment","q":"Which examination pairing is particularly relevant?","options":["Visual fields and optic-nerve assessment","Only visual acuity","Only IOP","Only slit-lamp corneal examination"],"answer":0,"explanation":"Glaucoma-related loss is assessed structurally and functionally with the optic nerve and visual fields."},{"label":"Diagnosis","q":"What diagnosis should be considered?","options":["Chronic glaucoma","Conjunctivitis","Cataract","Keratitis"],"answer":0,"explanation":"Progressive peripheral field loss is a classic functional pattern for glaucoma."},{"label":"Immediate Management","q":"What is important before labelling the cause?","options":["Confirm the defect and correlate it with the optic nerve and other glaucoma tests","Treat with antibiotic drops","Assume cataract","Ignore a normal IOP"],"answer":0,"explanation":"Field findings should be interpreted alongside structural and pressure assessments."},{"label":"Treatment","q":"Which treatments can reduce risk of progression?","options":["Pressure-lowering medicines, SLT and/or surgery according to the individual case","Topical antihistamines","Anti-VEGF injections for all cases","Cataract surgery alone"],"answer":0,"explanation":"Glaucoma management aims to reduce risk of progression using medicines, laser or surgery where appropriate."},{"label":"Follow-up & Prognosis","q":"What is the central long-term goal?","options":["Preserve remaining visual function by detecting and slowing progression","Restore the peripheral field immediately with drops","Stop all monitoring once symptoms are stable","Monitor only the red reflex"],"answer":0,"explanation":"Glaucoma damage is generally irreversible, so ongoing monitoring and prevention of further loss are central."}]},{"id":"c41","title":"Bitemporal Visual Field Loss","tag":"Neuro-ophthalmology","stem":"A 48-year-old has difficulty noticing objects from the sides. Confrontation fields suggest temporal loss in both eyes.","steps":[{"label":"Assessment","q":"What is the next useful confirmation?","options":["Formal visual-field testing and neuro-ophthalmic localisation","Only visual acuity","Only IOP","Only a slit-lamp exam"],"answer":0,"explanation":"Formal perimetry helps confirm and quantify the field defect."},{"label":"Diagnosis","q":"What localisation does a bitemporal defect suggest?","options":["The optic chiasm","The cornea","The lens","The conjunctiva"],"answer":0,"explanation":"Bitemporal hemianopia classically localises to the optic chiasm."},{"label":"Immediate Management","q":"What is the appropriate next step?","options":["Urgent medical/neurological assessment and imaging guided by the presentation","Treat as conjunctivitis","Routine cataract review","Topical antibiotic"],"answer":0,"explanation":"A chiasmal field defect can indicate intracranial pathology and needs appropriate neuroimaging/assessment."},{"label":"Treatment","q":"How is treatment determined?","options":["Treat the underlying cause, often through a multidisciplinary pathway","Topical anti-inflammatory eye drops","Panretinal laser","Cataract extraction"],"answer":0,"explanation":"Management depends on the intracranial cause."},{"label":"Follow-up & Prognosis","q":"What should follow-up include?","options":["Repeat visual fields and monitoring of the underlying lesion and visual function","Only IOP","Only redness","No visual monitoring"],"answer":0,"explanation":"Visual fields and the underlying lesion should be monitored because progression can affect both eyes."}]},{"id":"c42","title":"Homonymous Field Loss","tag":"Neuro-ophthalmology","stem":"A 70-year-old suddenly notices missing objects on one side. Confrontation testing suggests the same side of the visual field is missing from both eyes.","steps":[{"label":"Assessment","q":"Which test should confirm the pattern?","options":["Formal visual-field testing","Only Snellen acuity","Only IOP","Only red reflex"],"answer":0,"explanation":"Formal perimetry confirms and quantifies the defect."},{"label":"Diagnosis","q":"What localisation does a homonymous defect suggest?","options":["A post-chiasmal visual pathway lesion","The cornea","The lens","The conjunctiva"],"answer":0,"explanation":"Homonymous defects indicate post-chiasmal pathway involvement."},{"label":"Immediate Management","q":"What is the priority with a sudden new defect?","options":["Urgent neurological assessment for possible acute brain pathology","Routine eye examination next year","Topical antibiotics","Cataract surgery"],"answer":0,"explanation":"A sudden new homonymous field loss can represent an acute neurological event and requires urgent assessment."},{"label":"Treatment","q":"What is the treatment principle?","options":["Treat the underlying neurological cause and address rehabilitation/safety needs","Topical steroid drops","Panretinal laser","Anti-VEGF"],"answer":0,"explanation":"Management is directed at the cause and may include visual rehabilitation and safety advice."},{"label":"Follow-up & Prognosis","q":"What should follow-up address?","options":["Visual-field recovery/progression and functional adaptation","Only IOP","Only ocular redness","Only visual acuity"],"answer":0,"explanation":"Follow-up considers the neurological course and the person’s ability to function safely with the field deficit."}]},{"id":"c43","title":"Sudden Floaters with a Hazy View","tag":"Vitreous","stem":"A 65-year-old with diabetes develops sudden painless visual haze and numerous new floaters. The fundus view is poor.","steps":[{"label":"Assessment","q":"What is an important next step when the fundus cannot be seen?","options":["Ocular ultrasound where indicated","Only colour vision","Only visual acuity","Only Schirmer testing"],"answer":0,"explanation":"Ultrasound can help evaluate the posterior segment when media opacity obscures the view."},{"label":"Diagnosis","q":"Which diagnosis should be considered?","options":["Vitreous haemorrhage","Conjunctivitis","Cataract only","Anterior uveitis"],"answer":0,"explanation":"Sudden painless haze and floaters with an obscured fundus are compatible with vitreous haemorrhage."},{"label":"Immediate Management","q":"What is important?","options":["Urgent retinal assessment to identify the source and exclude retinal detachment","Routine annual screening","Topical antibiotic","Reassurance"],"answer":0,"explanation":"Vitreous haemorrhage can accompany retinal tears, detachment or proliferative disease and needs prompt assessment."},{"label":"Treatment","q":"What treatment depends on the cause?","options":["Address proliferative retinopathy or a retinal tear/detachment according to the retinal findings","Topical antihistamine","Cataract surgery for every patient","No treatment is ever required"],"answer":0,"explanation":"Treatment is cause-specific and may include laser, intravitreal therapy or surgery."},{"label":"Follow-up & Prognosis","q":"What determines prognosis?","options":["Underlying cause, retinal status and clearance of the haemorrhage","Only the degree of redness","Only IOP","Only visual acuity on day one"],"answer":0,"explanation":"Visual outcome depends on the cause and whether associated retinal pathology can be controlled."}]},{"id":"c44","title":"Unexpected Poor Vision after Cataract Surgery","tag":"Post-operative","stem":"Two weeks after cataract surgery, a patient has blurred vision without severe pain or redness. The macula is thickened on OCT.","steps":[{"label":"Assessment","q":"Which test is particularly helpful?","options":["OCT of the macula","Only IOP","Only visual fields","Only red-reflex testing"],"answer":0,"explanation":"OCT is useful for identifying postoperative macular oedema."},{"label":"Diagnosis","q":"What complication should be considered?","options":["Postoperative cystoid macular oedema","Acute angle closure","Conjunctivitis","Retinal detachment in every case"],"answer":0,"explanation":"Macular thickening after surgery with reduced vision can represent cystoid macular oedema."},{"label":"Immediate Management","q":"What is appropriate?","options":["Ophthalmic review to assess the macula and exclude other postoperative complications","Routine discharge without assessment","Only antibiotic drops","No examination"],"answer":0,"explanation":"Reduced vision after surgery needs assessment to determine the cause."},{"label":"Treatment","q":"Which treatment may be used depending on the clinical setting?","options":["Topical or intraocular anti-inflammatory treatment according to ophthalmic guidance","Panretinal photocoagulation","Cataract extraction again","Glaucoma surgery"],"answer":0,"explanation":"Treatment of postoperative macular oedema is specialist- and cause-dependent."},{"label":"Follow-up & Prognosis","q":"What is generally true?","options":["Many cases improve with treatment, but visual recovery depends on severity and other ocular disease","All cases cause permanent blindness","No follow-up is necessary","Only the IOP predicts outcome"],"answer":0,"explanation":"Prognosis is generally favourable in many cases but varies with chronicity, severity and coexisting disease."}]},{"id":"c45","title":"Sudden Vision Loss after New Floaters","tag":"Retina","stem":"A 74-year-old develops new floaters, then sudden visual loss. There is a shadow moving across the lower field.","steps":[{"label":"Assessment","q":"Which examination should be arranged urgently?","options":["Dilated retinal examination","Only a Snellen chart","Only IOP","Only visual fields"],"answer":0,"explanation":"The history requires urgent retinal examination."},{"label":"Diagnosis","q":"Which diagnosis is highest on the list?","options":["Retinal detachment","Cataract","Conjunctivitis","Optic neuritis"],"answer":0,"explanation":"A field shadow following new floaters is a classic retinal-detachment warning pattern."},{"label":"Immediate Management","q":"What is the correct urgency?","options":["Same-day/urgent ophthalmic assessment according to the local emergency pathway","Routine review next week","Topical antibiotic","Reassurance"],"answer":0,"explanation":"Delay can lead to permanent visual loss, so urgent assessment is required."},{"label":"Treatment","q":"Which treatment may be used?","options":["Retinal surgery and/or laser/cryotherapy depending on retinal findings","Topical steroid alone","Anti-VEGF in every case","Cataract surgery"],"answer":0,"explanation":"Treatment is tailored to the tear/detachment configuration and macular status."},{"label":"Follow-up & Prognosis","q":"Which feature is particularly important to document?","options":["Macular status and any involvement of central vision","Only conjunctival redness","Only pupil size","Only IOP"],"answer":0,"explanation":"Macular involvement is important for central visual prognosis."}]},{"id":"c46","title":"Reduced Vision with a Cloudy Cornea","tag":"Cornea","stem":"A 55-year-old presents with a very painful red eye and reduced vision. The cornea appears hazy and there is a focal white stromal lesion.","steps":[{"label":"Assessment","q":"Which bedside test is particularly useful?","options":["Fluorescein with slit-lamp examination","Only IOP","Only visual fields","Only a red reflex"],"answer":0,"explanation":"Fluorescein and slit-lamp examination help identify epithelial defects and characterise corneal pathology."},{"label":"Diagnosis","q":"What is the most likely diagnosis?","options":["Keratitis/corneal ulcer","Cataract","Conjunctivitis","Optic neuritis"],"answer":0,"explanation":"Painful red eye, reduced vision and corneal opacity/ulceration are characteristic of keratitis."},{"label":"Immediate Management","q":"What should happen?","options":["Urgent ophthalmic assessment","Routine optometry review","Only lubricants","No examination if the cornea is white"],"answer":0,"explanation":"A corneal ulcer is sight-threatening and needs urgent specialist assessment."},{"label":"Treatment","q":"What is the general treatment principle?","options":["Appropriate antimicrobial treatment when infection is suspected, under ophthalmic supervision","Topical steroid alone","Panretinal laser","Cataract surgery"],"answer":0,"explanation":"Suspected microbial keratitis requires prompt antimicrobial treatment; the regimen is determined by specialist assessment."},{"label":"Follow-up & Prognosis","q":"What determines visual prognosis?","options":["Location/depth of the ulcer and speed of effective treatment","Only the patient’s age","Only IOP","Only discharge"],"answer":0,"explanation":"Central or deep ulcers and delayed treatment can lead to scarring and permanent visual loss."}]},{"id":"c47","title":"Chronic Painless Visual Loss","tag":"Optic Nerve","stem":"A 58-year-old has slowly progressive reduction in vision in one eye. There is reduced colour vision and an afferent pupillary defect, with little external eye change.","steps":[{"label":"Assessment","q":"Which examination set is most useful?","options":["Visual acuity, colour vision, pupils, visual fields and optic-disc assessment","Only IOP","Only anterior-segment examination","Only discharge assessment"],"answer":0,"explanation":"These components help localise optic-nerve dysfunction and assess functional loss."},{"label":"Diagnosis","q":"What broad category should be considered?","options":["Optic neuropathy","Conjunctivitis","Cataract only","Allergic eye disease"],"answer":0,"explanation":"Reduced colour vision and an RAPD point towards an afferent optic pathway problem."},{"label":"Immediate Management","q":"What is the next step?","options":["Prompt neuro-ophthalmic assessment and investigation of the cause","Routine review without assessment","Topical antibiotics","Immediate retinal laser"],"answer":0,"explanation":"Progressive optic-nerve dysfunction needs appropriate neuro-ophthalmic work-up."},{"label":"Treatment","q":"Which approach is correct?","options":["Treat the underlying cause once identified","Topical steroid for every optic neuropathy","Cataract surgery regardless of findings","No treatment is ever needed"],"answer":0,"explanation":"Optic neuropathy is a syndrome with multiple causes, so treatment is cause-specific."},{"label":"Follow-up & Prognosis","q":"What determines visual outcome?","options":["The underlying cause and whether the optic nerve remains structurally/functionally compromised","Only IOP","Only visual acuity at one visit","Only conjunctival appearance"],"answer":0,"explanation":"Prognosis varies by the underlying optic neuropathy and the extent of irreversible damage."}]},{"id":"c48","title":"Unable to See the Fundus Clearly","tag":"Examination","stem":"During an eye examination, you cannot obtain an adequate view of the posterior pole because the media are hazy.","steps":[{"label":"Assessment","q":"What is the safest interpretation?","options":["Do not assume the fundus is normal simply because it cannot be visualised","The fundus is normal","The patient definitely has glaucoma","The patient definitely has cataract"],"answer":0,"explanation":"An inadequate view does not equal a normal fundus; further assessment may be needed."},{"label":"Diagnosis","q":"What could account for a poor fundus view?","options":["Media opacity such as cataract or vitreous haemorrhage","Only conjunctivitis","Only glaucoma","Only uveitis"],"answer":0,"explanation":"Lens or vitreous opacity can obscure the fundus and needs evaluation."},{"label":"Immediate Management","q":"What should you do next?","options":["Use the appropriate examination and imaging approach to identify the cause","Document “normal fundus”","Discharge without safety-netting","Only check the fellow eye"],"answer":0,"explanation":"An obscured view should prompt further assessment rather than a false-normal conclusion."},{"label":"Treatment","q":"How is treatment decided?","options":["According to the cause of the media opacity and any underlying posterior-segment disease","Treat every case with antibiotics","Panretinal laser for every case","Anti-VEGF for every case"],"answer":0,"explanation":"Treatment depends on what is causing the poor view and whether sight-threatening posterior pathology is present."},{"label":"Follow-up & Prognosis","q":"What is important?","options":["Ensure the posterior segment has been adequately assessed when clinically necessary","No further review if the patient has no pain","Only monitor IOP","Only monitor the red reflex"],"answer":0,"explanation":"A missed posterior-segment diagnosis can have serious consequences, so adequate visualisation or imaging matters."}]},{"id":"c49","title":"Red Eye with Preserved Vision but Severe Photophobia","tag":"Red Eye","stem":"A 31-year-old has a unilateral red eye with marked photophobia and mild blur. There is no discharge.","steps":[{"label":"Assessment","q":"Which history/examination features are most important?","options":["Pain, photophobia, acuity, pupil findings and corneal assessment","Only discharge","Only refraction","Only IOP"],"answer":0,"explanation":"These features help separate uveitis, keratitis and other serious red-eye causes from conjunctivitis."},{"label":"Diagnosis","q":"Which diagnoses should be prioritised?","options":["Keratitis or anterior uveitis","Cataract","Simple refractive error","Dry eye only"],"answer":0,"explanation":"Marked photophobia with a red eye and blur is a red flag for corneal or intraocular inflammation."},{"label":"Immediate Management","q":"What is the safest approach?","options":["Urgent ophthalmic assessment if sight-threatening pathology is suspected","Treat as conjunctivitis without examination","Use an eye patch and discharge","Routine review in a month"],"answer":0,"explanation":"Pain/photophobia and reduced vision make a simple conjunctivitis pathway unsafe without assessment."},{"label":"Treatment","q":"What treatment is chosen after diagnosis?","options":["Corneal infection needs antimicrobial therapy; anterior uveitis needs anti-inflammatory treatment under ophthalmology","Antibiotic for every red eye","Panretinal laser","Cataract surgery"],"answer":0,"explanation":"Treatment depends on the cause; keratitis and uveitis require different management."},{"label":"Follow-up & Prognosis","q":"Which principle is important?","options":["Follow-up is tailored to the diagnosis because untreated keratitis or uveitis can threaten vision","No follow-up is needed if redness improves","Only IOP predicts outcome","The red eye cannot recur"],"answer":0,"explanation":"Both keratitis and uveitis can recur or cause complications, so appropriate follow-up is essential."}]},{"id":"c50","title":"Systematic Eye Examination in a New Patient","tag":"Examination","stem":"A foundation doctor is asked to assess a patient with an unexplained visual complaint. The patient is comfortable and there is no obvious external abnormality.","steps":[{"label":"Assessment","q":"Which sequence is a sensible core approach?","options":["Visual acuity → pupils → visual fields → eye movements → anterior segment → fundoscopy","Fundoscopy only","IOP before any history or vision testing","Treat first and examine later"],"answer":0,"explanation":"A structured sequence reduces missed findings and supports localisation."},{"label":"Diagnosis","q":"What is the value of the systematic sequence?","options":["It helps localise whether the problem may be refractive/media, retinal, optic-nerve or neurological","It guarantees a diagnosis from one sign","It makes history unnecessary","It replaces specialist testing"],"answer":0,"explanation":"Systematic examination helps build and localise the differential but does not replace targeted tests or specialist assessment."},{"label":"Immediate Management","q":"What should happen when a red flag appears?","options":["Escalate according to urgency rather than continuing routine assessment alone","Ignore the red flag if acuity is normal","Finish the whole examination before considering referral in every case","Provide reassurance first"],"answer":0,"explanation":"The examination should be adapted when sight- or life-threatening features emerge."},{"label":"Treatment","q":"What should the examiner do before selecting disease-specific treatment?","options":["Use the examination findings to establish the likely diagnosis and follow the appropriate local pathway","Choose antibiotics for all eye complaints","Choose steroid drops for all red eyes","Start glaucoma drops for any visual symptom"],"answer":0,"explanation":"Treatment should follow diagnosis and local guidance rather than symptoms alone."},{"label":"Follow-up & Prognosis","q":"What makes the examination clinically useful?","options":["Clear documentation of visual acuity, laterality and key findings to support continuity and follow-up","Only a verbal description","Only recording the diagnosis","No documentation if referral occurs"],"answer":0,"explanation":"Good documentation allows progression and response to treatment to be assessed over time."}]}];

function openTopic(i){
  const topic=topics[i][0];
  pushPage("topic","findings",{topic,unitKind:"topic",unitKey:topic,readUnlocked:false});
}
function openConditionByIndex(i){openCondition(conditions[i].name)}
function openCondition(name){
  const condition=conditions.find(c=>c.name===name)||conditions[0];
  pushPage("condition","learn",{condition,unitKind:"condition",unitKey:condition.name,readUnlocked:false});
}
function openFinding(i){
  const finding=findings[i];
  pushPage("finding","findings",{finding,unitKind:"finding",unitKey:finding.name,readUnlocked:false});
}
function openImages(){pushPage("images","findings")}
function openCase(i){
  const index=Math.max(0,Math.min(cases.length-1,Number(i)||0));
  pushPage("caseq","cases",{caseIndex:index,casePart:0,caseSelected:null,caseResponses:{}});
}
function caseFor(name){
  const idx=cases.findIndex(c=>c.title.toLowerCase().includes(String(name).toLowerCase())||c.stem.toLowerCase().includes(String(name).toLowerCase()));
  openCase(idx>=0?idx:0);
}
function selectCaseAnswer(i){if(!Object.prototype.hasOwnProperty.call(state.caseResponses||{},state.casePart)){state.caseSelected=i;render();setNav("cases")}}
function submitCasePart(){
  if(state.caseSelected===null)return;
  const responses=state.caseResponses||{};
  responses[state.casePart]=state.caseSelected;
  state.caseResponses=responses;
  render();setNav("cases");
}
function prevCasePart(){
  if(state.casePart>0){state.casePart--;state.caseSelected=Object.prototype.hasOwnProperty.call(state.caseResponses||{},state.casePart)?state.caseResponses[state.casePart]:null;render();setNav("cases");window.scrollTo(0,0)}
}
function nextCasePart(){
  if(state.casePart>=cases[state.caseIndex].steps.length-1)return;
  state.casePart++;state.caseSelected=Object.prototype.hasOwnProperty.call(state.caseResponses||{},state.casePart)?state.caseResponses[state.casePart]:null;render();setNav("cases");window.scrollTo(0,0);
}
function finishCase(){
  const c=cases[state.caseIndex];
  if(Object.keys(state.caseResponses||{}).length<c.steps.length){alert("Complete all five parts of the case first.");return;}
  markProgress("cases",c.id);
  render();setNav("cases");
}
function selectAnswer(i){if(!state.feedback){state.selected=i;render();setNav("questions")}}
function submitAnswer(){
  if(state.selected===null)return;
  state.feedback=true;
  markProgress("questions",String(quiz[state.qIndex].id));
  render();setNav("questions");
}
function prevQuestion(){
  state.qIndex=(state.qIndex-1+quiz.length)%quiz.length;state.selected=null;state.feedback=false;render();setNav("questions");window.scrollTo(0,0)
}
function nextQuestion(){state.qIndex=(state.qIndex+1)%quiz.length;state.selected=null;state.feedback=false;render();setNav("questions");window.scrollTo(0,0)}
function openRights(){pushPage("rights","")}
function showHelp(){alert("Use Learn for ophthalmic conditions. Use Examination for eye examination skills, clinical assessment, findings and original teaching diagrams. Each learning item only counts towards course progress after you have read all its content and completed its topic question. Questions are content-based practice; Clinical Cases are longer multi-part scenarios. Progress is saved in this browser. Reset Progress opens a confirmation prompt before erasing all saved progress.")}
window.addEventListener("keydown",e=>{if(e.key==="Escape")closeResetModal()});
goHome();
